create unique index if not exists compute_jobs_one_per_order on public.compute_jobs(order_id);

create or replace function private.validate_compute_job_order() returns trigger language plpgsql set search_path='' as $$
begin
 if not exists(select 1 from public.business_orders o where o.id=new.order_id and o.unit_code='compute') then raise exception 'Compute job must belong to a compute order'; end if;
 if new.estimated_hours is not null and new.estimated_hours<=0 then raise exception 'Estimated hours must be positive'; end if;
 return new;
end $$;
drop trigger if exists validate_compute_job_order on public.compute_jobs;
create trigger validate_compute_job_order before insert or update on public.compute_jobs for each row execute function private.validate_compute_job_order();

create or replace function private.validate_compute_usage_order() returns trigger language plpgsql set search_path='' as $$
begin
 if not exists(select 1 from public.compute_jobs j join public.business_orders o on o.id=j.order_id where j.order_id=new.order_id and o.unit_code='compute') then raise exception 'Usage must belong to an existing compute job'; end if;
 if coalesce(new.hours,0)<0 or coalesce(new.credits_used,0)<0 then raise exception 'Usage values cannot be negative'; end if;
 return new;
end $$;
drop trigger if exists validate_compute_usage_order on public.compute_usage_records;
create trigger validate_compute_usage_order before insert or update on public.compute_usage_records for each row execute function private.validate_compute_usage_order();

create or replace function public.submit_business_request(target_unit text,request_title text,request_requirements text,request_quantity integer,request_specs jsonb default '{}'::jsonb,catalog_service uuid default null) returns uuid
language plpgsql set search_path='' as $$
declare request_id uuid; estimated numeric;
begin
 if auth.uid() is null or target_unit not in ('fabrication','compute','digital_business','business_centre') or length(trim(request_title))<3
 or length(trim(request_requirements))<10 or request_quantity<1 or request_quantity>100000 or jsonb_typeof(request_specs)<>'object'
 or octet_length(request_specs::text)>16000 then raise exception 'Invalid service request'; end if;
 if catalog_service is not null and not exists(select 1 from public.business_catalog c where c.id=catalog_service and c.unit_code=target_unit and c.is_active) then raise exception 'Selected service is unavailable'; end if;
 if target_unit='compute' then
   begin estimated:=nullif(request_specs->>'estimated_hours','')::numeric; exception when invalid_text_representation then raise exception 'Estimated compute hours must be numeric'; end;
   if estimated is not null and estimated<=0 then raise exception 'Estimated compute hours must be positive'; end if;
 end if;
 insert into public.business_orders(user_id,unit_code,service_id,title,requirements,quantity,specifications)
 values(auth.uid(),target_unit,catalog_service,trim(request_title),trim(request_requirements),request_quantity,request_specs) returning id into request_id;
 if target_unit='fabrication' then
  insert into public.fabrication_jobs(order_id,process,material,dimensions,status) values(request_id,coalesce(nullif(request_specs->>'process',''),'FDM'),request_specs->>'material',request_specs->>'dimensions','review');
 elsif target_unit='compute' then
  insert into public.compute_jobs(order_id,workload_type,compute_profile,dataset_notes,estimated_hours,status)
  values(request_id,coalesce(nullif(request_specs->>'workload_type',''),'Project compute'),request_specs->>'compute_profile',request_specs->>'dataset_notes',estimated,'review');
 end if;
 return request_id;
end $$;
revoke all on function public.submit_business_request(text,text,text,integer,jsonb,uuid) from public,anon;
grant execute on function public.submit_business_request(text,text,text,integer,jsonb,uuid) to authenticated,service_role;

create or replace function public.issue_consult_quotation(p_project_id uuid,p_amount numeric,p_scope_summary text,p_valid_until date default null)
returns uuid language plpgsql security definer set search_path='' as $$
declare v_id uuid;
begin
 if (select auth.uid()) is null or not private.has_product_access('consult','edit') then raise exception 'Consult edit access required'; end if;
 if p_amount is null or p_amount <= 0 then raise exception 'Quotation amount must be greater than zero'; end if;
 if length(trim(coalesce(p_scope_summary,''))) < 3 then raise exception 'Quotation scope is required'; end if;
 if not exists(select 1 from public.consult_projects where id=p_project_id) then raise exception 'Project not found'; end if;
 insert into public.consult_quotations(project_id,amount,scope_summary,valid_until,status)
 values(p_project_id,p_amount,trim(p_scope_summary),p_valid_until,'sent') returning id into v_id;
 update public.consult_projects set quoted_amount=p_amount,updated_at=now() where id=p_project_id;
 return v_id;
end $$;
revoke all on function public.issue_consult_quotation(uuid,numeric,text,date) from public;
grant execute on function public.issue_consult_quotation(uuid,numeric,text,date) to authenticated;

create or replace function public.respond_consult_proposal(p_proposal uuid,p_action text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v public.consult_proposals; inv uuid; q public.consult_quotations;
begin
 if p_action not in ('accepted','revision_requested','rejected') then raise exception 'Invalid action'; end if;
 select * into v from public.consult_proposals where id=p_proposal and user_id=(select auth.uid()) for update;
 if not found then raise exception 'Proposal not found'; end if;
 if v.status not in ('sent','revision_requested') then raise exception 'Proposal is not awaiting response'; end if;
 if p_action='accepted' then
   select * into q from public.consult_quotations where project_id=v.project_id and status='accepted' order by created_at desc limit 1;
   if not found then raise exception 'Accept the project quotation before accepting the proposal'; end if;
   if q.amount is null or q.amount<=0 then raise exception 'A valid positive quotation is required before invoicing'; end if;
 end if;
 update public.consult_proposals set status=p_action,accepted_at=case when p_action='accepted' then now() else accepted_at end,revision_requested_at=case when p_action='revision_requested' then now() else revision_requested_at end,rejected_at=case when p_action='rejected' then now() else rejected_at end,updated_at=now() where id=v.id;
 if p_action='accepted' then
   insert into public.consult_invoices(project_id,proposal_id,invoice_number,title,amount,currency,due_at,status)
   values(v.project_id,v.id,'CONS-'||to_char(now(),'YYYYMMDD')||'-'||upper(substr(replace(v.id::text,'-',''),1,6)),v.title,q.amount,'NGN',current_date+7,'unpaid')
   returning id into inv;
   update public.consult_projects set quoted_amount=q.amount,outstanding_amount=q.amount,updated_at=now() where id=v.project_id;
 end if;
 return jsonb_build_object('status',p_action,'invoice_id',inv);
end $$;

create or replace function public.respond_consult_quotation(p_quotation uuid,p_action text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare q public.consult_quotations; owner_id uuid;
begin
 if p_action not in ('accepted','rejected') then raise exception 'Invalid quotation action'; end if;
 select cq.*,cp.user_id into q.id,q.project_id,q.quote_number,q.amount,q.scope_summary,q.valid_until,q.status,q.created_at,q.updated_at,owner_id
 from public.consult_quotations cq join public.consult_projects cp on cp.id=cq.project_id
 where cq.id=p_quotation for update;
 if q.id is null or owner_id<>(select auth.uid()) then raise exception 'Quotation not found'; end if;
 if q.status<>'sent' then raise exception 'Quotation is not awaiting response'; end if;
 if q.valid_until is not null and q.valid_until<current_date then
   update public.consult_quotations set status='expired',updated_at=now() where id=q.id;
   raise exception 'Quotation has expired';
 end if;
 update public.consult_quotations set status=p_action,updated_at=now() where id=q.id;
 if p_action='accepted' then update public.consult_projects set quoted_amount=q.amount,updated_at=now() where id=q.project_id; end if;
 return jsonb_build_object('status',p_action,'quotation_id',q.id);
end $$;
revoke all on function public.respond_consult_quotation(uuid,text) from public;
grant execute on function public.respond_consult_quotation(uuid,text) to authenticated;

create or replace function public.schoolpro_subscription_entitlements(p_school uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare s public.schoolpro_subscriptions; p public.schoolpro_plan_catalog; base jsonb; ov jsonb; school_state public.school_status;
begin
 if not(public.schoolpro_member_can_manage(p_school) or exists(select 1 from public.schoolpro_members m where m.school_id=p_school and m.user_id=auth.uid()) or private.is_admin(array['super_admin']::public.user_role[])) then raise exception 'Not authorized'; end if;
 select status into school_state from public.schoolpro_schools where id=p_school;
 if school_state is distinct from 'active'::public.school_status then return jsonb_build_object('active',false,'tier','none','website',false,'cbt',false,'advanced_reports',false,'custom_branding',false,'reason','subscription_or_control_center_activation_required'); end if;
 select * into s from public.schoolpro_subscriptions where school_id=p_school order by updated_at desc limit 1;
 if s.id is null or s.status<>'active' or (s.renews_at is not null and s.renews_at<=now()) then return jsonb_build_object('active',false,'tier','none','website',false,'cbt',false,'advanced_reports',false,'custom_branding',false,'reason','active_subscription_required'); end if;
 select * into p from public.schoolpro_plan_catalog where tier=s.tier;
 base:=jsonb_build_object('active',true,'tier',s.tier,'customization_level',s.customization_level)||coalesce(p.features,'{}'::jsonb);
 select coalesce(jsonb_object_agg(feature,enabled),'{}'::jsonb) into ov from public.schoolpro_feature_overrides where school_id=p_school;
 return base||ov;
end $$;

create or replace function public.control_center_activate_schoolpro(p_school uuid,p_tier text default 'starter',p_reason text default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r timestamptz;
begin
 if not private.has_product_access('schoolpro','approve') then raise exception 'SchoolPro approval access required'; end if;
 if length(trim(coalesce(p_reason,'')))<3 then raise exception 'Activation reason is required'; end if;
 if not exists(select 1 from public.schoolpro_schools where id=p_school) then raise exception 'School not found'; end if;
 if not exists(select 1 from public.schoolpro_subscription_catalog where code=p_tier and active=true) then raise exception 'Active SchoolPro plan not found'; end if;
 r:=now()+interval '1 year';
 insert into public.schoolpro_subscriptions(school_id,tier,billing_cycle,amount,status,starts_at,renews_at,managed_by_ihlink,updated_at)
 values(p_school,p_tier,'annual',0,'active',now(),r,true,now())
 on conflict(school_id) do update set tier=excluded.tier,billing_cycle='annual',status='active',starts_at=now(),renews_at=r,managed_by_ihlink=true,updated_at=now();
 update public.schoolpro_schools set status='active',plan=p_tier,updated_at=now() where id=p_school;
 insert into public.activity_logs(user_id,action,entity_type,entity_id,metadata)
 values(auth.uid(),'schoolpro_control_center_activation','schoolpro_school',p_school,jsonb_build_object('tier',p_tier,'reason',trim(p_reason),'commercial_override',true));
 return jsonb_build_object('status','active','school_id',p_school,'tier',p_tier,'renews_at',r,'source','control_center');
end $$;
revoke all on function public.control_center_activate_schoolpro(uuid,text,text) from public;
grant execute on function public.control_center_activate_schoolpro(uuid,text,text) to authenticated;

create or replace function public.finalize_schoolpro_subscription(p_intent uuid,p_transaction_ref text,p_amount numeric)
returns jsonb language plpgsql security definer set search_path='' as $$
declare i public.schoolpro_subscription_intents%rowtype;c public.schoolpro_subscription_catalog%rowtype;tx public.payment_transactions%rowtype;existing public.schoolpro_subscriptions%rowtype;r timestamptz;
begin
 if p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) or nullif(btrim(p_transaction_ref),'') is null then raise exception 'Verified exact subscription payment required';end if;
 select * into i from public.schoolpro_subscription_intents where id=p_intent for update;if i.id is null then raise exception 'Subscription payment intent unavailable';end if;
 if i.billing_cycle<>'annual' then raise exception 'SchoolPro subscriptions are billed annually';end if;
 if i.status='paid' then if i.transaction_ref=p_transaction_ref and i.amount=p_amount then return jsonb_build_object('status','already_paid','school_id',i.school_id);end if;raise exception 'Subscription intent already settled by another transaction';end if;
 select * into tx from public.payment_transactions where provider='billstack' and transaction_ref=p_transaction_ref for update;
 if i.status<>'pending' or i.amount<>p_amount or tx.id is null or tx.status not in('verified','credited') or tx.credited_at is not null or tx.amount<>p_amount or tx.currency<>'NGN' or tx.user_id is distinct from i.payer_user_id or tx.platform_code is distinct from 'schoolpro' or tx.virtual_account_id is distinct from i.virtual_account_id then raise exception 'Verified transaction ownership, platform or replay validation failed';end if;
 select * into c from public.schoolpro_subscription_catalog where id=i.catalog_id and active=true;if c.id is null then raise exception 'Subscription plan is unavailable';end if;
 select * into existing from public.schoolpro_subscriptions where school_id=i.school_id for update;
 r:=case when existing.id is not null and existing.status='active' and existing.renews_at is not null and existing.renews_at>now() then existing.renews_at+interval '1 year' else now()+interval '1 year' end;
 insert into public.schoolpro_subscriptions(school_id,tier,billing_cycle,amount,status,starts_at,renews_at,managed_by_ihlink,updated_at)
 values(i.school_id,c.code,'annual',i.amount,'active',now(),r,true,now())
 on conflict(school_id) do update set tier=excluded.tier,billing_cycle='annual',amount=excluded.amount,status='active',starts_at=coalesce(public.schoolpro_subscriptions.starts_at,now()),renews_at=r,managed_by_ihlink=true,updated_at=now();
 update public.schoolpro_schools set status='active',plan=c.code,updated_at=now() where id=i.school_id;
 update public.schoolpro_subscription_intents set status='paid',transaction_ref=p_transaction_ref,paid_at=now(),updated_at=now() where id=i.id;
 update public.payment_transactions set status='credited',credited_at=now(),updated_at=now() where id=tx.id;
 return jsonb_build_object('status','active','school_id',i.school_id,'tier',c.code,'billing_cycle','annual','renews_at',r);
end $$;

-- Preserve existing records and require secured commercial transitions.
create unique index consult_one_accepted_quotation_per_project
 on public.consult_quotations(project_id) where status='accepted';
alter table public.consult_invoices add column quotation_id uuid references public.consult_quotations(id);
create unique index consult_one_invoice_per_quotation
 on public.consult_invoices(quotation_id) where quotation_id is not null;
create unique index consult_one_invoice_per_proposal
 on public.consult_invoices(proposal_id) where proposal_id is not null;
alter table public.consult_invoices add constraint consult_invoice_positive_amount check(amount>0);

-- Clients and staff must use the RPCs; SELECT/RLS and service-role finalizers remain intact.
revoke insert,update,delete on public.consult_quotations,public.consult_proposals,
 public.consult_invoices from public,anon,authenticated;

create or replace function public.issue_consult_quotation(
 p_project_id uuid,p_amount numeric,p_scope_summary text,p_valid_until date default null
) returns uuid language plpgsql security definer set search_path='' as $$
declare v_id uuid; v_actor uuid := auth.uid();
begin
 if v_actor is null or not coalesce(private.has_product_access('consult','edit'),false) then
  raise exception 'Consult edit access required';
 end if;
 if p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) then
  raise exception 'Quotation amount must be positive with at most two decimal places';
 end if;
 if length(trim(coalesce(p_scope_summary,'')))<3 then raise exception 'Quotation scope is required'; end if;
 if p_valid_until<current_date then raise exception 'Quotation validity must not be in the past'; end if;
 perform 1 from public.consult_projects where id=p_project_id for update;
 if not found then raise exception 'Project not found'; end if;
 if exists(select 1 from public.consult_quotations where project_id=p_project_id and status='accepted') then
  raise exception 'Project already has an accepted quotation; use the approved change workflow';
 end if;
 insert into public.consult_quotations(project_id,amount,scope_summary,valid_until,status)
 values(p_project_id,p_amount,trim(p_scope_summary),p_valid_until,'sent') returning id into v_id;
 update public.consult_projects set quoted_amount=p_amount,updated_at=now() where id=p_project_id;
 insert into public.consult_activity_logs(project_id,actor_user_id,action,details)
 values(p_project_id,v_actor,'quotation_issued',jsonb_build_object('quotation_id',v_id,'amount',p_amount));
 return v_id;
end $$;

create or replace function public.respond_consult_quotation(p_quotation uuid,p_action text)
 returns jsonb language plpgsql security definer set search_path='' as $$
declare q public.consult_quotations; v_project uuid; v_owner uuid; v_actor uuid := auth.uid();
begin
 if v_actor is null then raise exception 'Authentication required'; end if;
 if p_action is null or p_action not in('accepted','rejected') then raise exception 'Invalid quotation action'; end if;
 select project_id into v_project from public.consult_quotations where id=p_quotation;
 select user_id into v_owner from public.consult_projects where id=v_project for update;
 if not found or v_owner is distinct from v_actor then raise exception 'Quotation not found'; end if;
 select * into q from public.consult_quotations where id=p_quotation and project_id=v_project for update;
 if not found then raise exception 'Quotation not found'; end if;
 if q.status=p_action then return jsonb_build_object('status',q.status,'quotation_id',q.id); end if;
 if q.status<>'sent' then raise exception 'Quotation is not awaiting response'; end if;
 if q.valid_until<current_date then raise exception 'Quotation has expired'; end if;
 if p_action='accepted' then
  if exists(select 1 from public.consult_quotations where project_id=v_project and status='accepted' and id<>q.id) then
   raise exception 'Project already has an accepted quotation';
  end if;
  if q.amount is null or q.amount<=0 then raise exception 'A positive quotation is required'; end if;
 end if;
 update public.consult_quotations set status=p_action,updated_at=now() where id=q.id;
 if p_action='accepted' then
  with superseded as (
   update public.consult_quotations set status='expired',updated_at=now()
   where project_id=v_project and id<>q.id and status in('draft','sent') returning id
  ) insert into public.consult_activity_logs(project_id,actor_user_id,action,details)
   select v_project,v_actor,'quotation_superseded',jsonb_build_object('quotation_id',id,'accepted_quotation_id',q.id) from superseded;
  update public.consult_projects set quoted_amount=q.amount,updated_at=now() where id=v_project;
 end if;
 insert into public.consult_activity_logs(project_id,actor_user_id,action,details)
 values(v_project,v_actor,'quotation_'||p_action,jsonb_build_object('quotation_id',q.id,'amount',q.amount));
 return jsonb_build_object('status',p_action,'quotation_id',q.id);
end $$;

create or replace function public.respond_consult_proposal(p_proposal uuid,p_action text)
 returns jsonb language plpgsql security definer set search_path='' as $$
declare v public.consult_proposals; q public.consult_quotations; inv uuid;
 v_project uuid; v_owner uuid; v_actor uuid := auth.uid();
begin
 if v_actor is null then raise exception 'Authentication required'; end if;
 if p_action is null or p_action not in('accepted','revision_requested','rejected') then raise exception 'Invalid action'; end if;
 select project_id into v_project from public.consult_proposals where id=p_proposal;
 select user_id into v_owner from public.consult_projects where id=v_project for update;
 if not found or v_owner is distinct from v_actor then raise exception 'Proposal not found'; end if;
 select * into v from public.consult_proposals where id=p_proposal and user_id=v_actor for update;
 if not found then raise exception 'Proposal not found'; end if;
 if v.status='accepted' and p_action='accepted' then
  select id into inv from public.consult_invoices where proposal_id=v.id;
  return jsonb_build_object('status','accepted','invoice_id',inv);
 end if;
 if v.status not in('sent','revision_requested') then raise exception 'Proposal is not awaiting response'; end if;
 if exists(select 1 from public.consult_proposals where project_id=v_project and version>v.version) then
  raise exception 'Review the latest proposal version';
 end if;
 if v.valid_until<current_date then raise exception 'Proposal has expired'; end if;
 if p_action='accepted' then
  select * into q from public.consult_quotations where project_id=v_project and status='accepted';
  if not found or q.amount is null or q.amount<=0 then raise exception 'Accept a valid positive quotation before accepting the proposal'; end if;
  if exists(select 1 from public.consult_invoices where quotation_id=q.id) then
   raise exception 'This quotation already has an invoice';
  end if;
 end if;
 update public.consult_proposals set status=p_action,
  accepted_at=case when p_action='accepted' then now() else accepted_at end,
  revision_requested_at=case when p_action='revision_requested' then now() else revision_requested_at end,
  rejected_at=case when p_action='rejected' then now() else rejected_at end,updated_at=now() where id=v.id;
 if p_action='accepted' then
  insert into public.consult_invoices(project_id,proposal_id,quotation_id,invoice_number,title,amount,currency,due_at,status)
  values(v_project,v.id,q.id,'CONS-'||to_char(now(),'YYYYMMDD')||'-'||upper(replace(v.id::text,'-','')),v.title,q.amount,'NGN',current_date+7,'issued')
  returning id into inv;
  update public.consult_projects set quoted_amount=q.amount,
   outstanding_amount=(select coalesce(sum(greatest(amount-coalesce(amount_paid,0),0)),0) from public.consult_invoices where project_id=v_project and status<>'cancelled'),
   updated_at=now() where id=v_project;
 end if;
 insert into public.consult_activity_logs(project_id,actor_user_id,action,details)
 values(v_project,v_actor,'proposal_'||p_action,jsonb_build_object('proposal_id',v.id,'invoice_id',inv));
 return jsonb_build_object('status',p_action,'invoice_id',inv);
end $$;

revoke all on function public.issue_consult_quotation(uuid,numeric,text,date),
 public.respond_consult_quotation(uuid,text),public.respond_consult_proposal(uuid,text) from public,anon;
grant execute on function public.issue_consult_quotation(uuid,numeric,text,date),
 public.respond_consult_quotation(uuid,text),public.respond_consult_proposal(uuid,text) to authenticated;

-- Retire outstanding alternatives to an already accepted quotation, without deleting history.
with superseded as (
 update public.consult_quotations q set status='expired',updated_at=now()
 where q.status in('sent','draft') and exists(
  select 1 from public.consult_quotations a where a.project_id=q.project_id and a.status='accepted' and a.id<>q.id
 ) returning q.id,q.project_id
) insert into public.consult_activity_logs(project_id,action,details)
 select project_id,'quotation_superseded',jsonb_build_object('quotation_id',id,'source','consult_commercial_transition_safety') from superseded;

create or replace function public.finalize_consult_billstack_payment(p_intent uuid,p_transaction_ref text,p_amount numeric)
 returns jsonb language plpgsql security definer set search_path='' as $$
declare i public.consult_payment_intents; inv public.consult_invoices; tx public.payment_transactions;
begin
 if p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) or nullif(btrim(p_transaction_ref),'') is null then raise exception 'Verified exact payment required'; end if;
 select * into i from public.consult_payment_intents where id=p_intent for update;
 if i.id is null then raise exception 'Payment intent unavailable'; end if;
 if i.status='paid' then
  if i.transaction_ref=p_transaction_ref and i.amount=p_amount then return jsonb_build_object('status','already_paid','intent_id',i.id); end if;
  raise exception 'Intent already settled by another transaction';
 end if;
 select * into tx from public.payment_transactions where provider='billstack' and transaction_ref=p_transaction_ref for update;
 if i.status<>'pending' or tx.id is null or tx.status not in('verified','credited') or tx.credited_at is not null or tx.amount<>p_amount or tx.currency<>'NGN'
  or tx.user_id is distinct from i.user_id or tx.platform_code is distinct from 'consult' or tx.virtual_account_id is distinct from i.virtual_account_id then
  raise exception 'Verified transaction ownership, platform or replay validation failed';
 end if;
 select * into inv from public.consult_invoices where id=i.invoice_id for update;
 if inv.id is null or inv.status not in('issued','part_paid','overdue') or inv.project_id<>i.project_id or inv.currency<>'NGN'
  or not exists(select 1 from public.consult_projects p where p.id=i.project_id and p.user_id=i.user_id)
  or p_amount<>i.amount or p_amount<>inv.amount-coalesce(inv.amount_paid,0) then raise exception 'Invoice linkage or exact amount validation failed'; end if;
 if exists(select 1 from public.consult_payments where payment_reference=p_transaction_ref) then raise exception 'Duplicate transaction'; end if;
 insert into public.consult_payments(project_id,payment_reference,amount,description,status,paid_at)
 values(i.project_id,p_transaction_ref,p_amount,'BillStack payment for '||inv.invoice_number,'paid',now());
 update public.consult_invoices set amount_paid=amount,status='paid',paid_at=now(),payment_reference=p_transaction_ref,updated_at=now() where id=inv.id;
 update public.consult_payment_intents set status='paid',transaction_ref=p_transaction_ref,paid_at=now(),updated_at=now() where id=i.id;
 update public.payment_transactions set status='credited',credited_at=now(),updated_at=now() where id=tx.id;
 update public.consult_projects set status=case when status in('pending','planning','quoted') then 'active' else status end,
  stage=case when stage in('proposal','quotation','planning') then 'delivery' else stage end,
  outstanding_amount=(select coalesce(sum(greatest(amount-coalesce(amount_paid,0),0)),0) from public.consult_invoices where project_id=i.project_id and status<>'cancelled'),
  updated_at=now() where id=i.project_id;
 insert into public.consult_activity_logs(project_id,actor_user_id,action,details)
 values(i.project_id,i.user_id,'invoice_settled',jsonb_build_object('invoice_id',inv.id,'intent_id',i.id,'transaction_ref',p_transaction_ref,'amount',p_amount,'source','verified_billstack'));
 return jsonb_build_object('status','paid','invoice_id',inv.id,'project_id',i.project_id);
end $$;
