-- Preserve existing project history; prevent new duplicates on request conversion.
create or replace function private.guard_consult_request_project()
returns trigger language plpgsql security definer set search_path = public, pg_temp as $$
declare r public.consult_requests;
begin
  if new.request_id is null then return new; end if;
  if tg_op = 'UPDATE' and new.request_id is not distinct from old.request_id then return new; end if;
  select * into r from public.consult_requests where id = new.request_id for update;
  if not found then raise exception 'Consult request not found'; end if;
  if new.user_id is distinct from r.user_id then raise exception 'Project owner must match the request owner'; end if;
  if exists(select 1 from public.consult_projects where request_id = new.request_id and id <> new.id) then
    raise exception 'This request already has a project. Open the existing project instead.';
  end if;
  return new;
end $$;
revoke all on function private.guard_consult_request_project() from public, anon, authenticated;
create trigger consult_request_project_guard before insert or update of request_id
on public.consult_projects for each row execute function private.guard_consult_request_project();

create or replace function public.convert_consult_request(p_request uuid)
returns uuid language plpgsql security definer set search_path = public, pg_temp as $$
declare r public.consult_requests; project_id uuid;
begin
  if auth.uid() is null or not coalesce(private.has_product_access('consult','edit'),false) then
    raise exception 'Consult edit access required';
  end if;
  select * into r from public.consult_requests where id = p_request for update;
  if not found then raise exception 'Consult request not found'; end if;
  -- Historical duplicates are retained. Prefer the project with an accepted quote.
  select p.id into project_id from public.consult_projects p where p.request_id = r.id
  order by exists(select 1 from public.consult_quotations q where q.project_id=p.id and q.status='accepted') desc,
    p.created_at, p.id limit 1;
  if project_id is not null then return project_id; end if;
  if r.status in ('declined','closed') then raise exception 'This request is closed or declined'; end if;
  insert into public.consult_projects(user_id,request_id,name,service_category,stage,progress,status)
    values(r.user_id,r.id,r.title,r.service_category,'discovery',0,'active') returning id into project_id;
  insert into public.consult_milestones(project_id,title,description,status,sort_order) values
    (project_id,'Discovery and requirements','Confirm users, scope and success criteria','pending',10),
    (project_id,'Proposal and approval','Review scope, quotation and delivery plan','pending',20),
    (project_id,'Implementation','Build and validate the agreed solution','pending',30),
    (project_id,'Handover','Deployment, training and acceptance','pending',40);
  update public.consult_requests set status='accepted',updated_at=now() where id=r.id;
  insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
    values(auth.uid(),'consult_request_converted','consult','consult_project',project_id::text,
      jsonb_build_object('request_id',r.id));
  return project_id;
end $$;
revoke all on function public.convert_consult_request(uuid) from public, anon;
grant execute on function public.convert_consult_request(uuid) to authenticated;

CREATE OR REPLACE FUNCTION public.register_consult_proposal(p_project_id uuid, p_title text, p_valid_until date, p_storage_path text, p_original_filename text, p_mime_type text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid;v_version integer;v_id uuid;
begin
 if (select auth.uid()) is null or not coalesce(private.has_product_access('consult','edit'),false) then
  raise exception 'Consult edit access required';
 end if;
 if length(trim(coalesce(p_title,''))) < 3 or length(trim(coalesce(p_original_filename,''))) < 1 then
  raise exception 'A proposal title and filename are required';
 end if;
 if split_part(p_storage_path,'/',1) <> (select auth.uid())::text then
  raise exception 'The uploaded file must belong to this account';
 end if;
 select user_id into v_owner from public.consult_projects where id=p_project_id for update;
 if v_owner is null then raise exception 'Project not found'; end if;
 if not exists(select 1 from public.consult_quotations where project_id=p_project_id and status='accepted' and amount>0 and (valid_until is null or valid_until>=current_date)) then raise exception 'Accept a valid monetary quotation for this project before sending a proposal'; end if;
 if not exists(select 1 from storage.objects where bucket_id='consult-documents' and name=p_storage_path) then
  raise exception 'Proposal file was not uploaded';
 end if;
 select coalesce(max(version),0)+1 into v_version from public.consult_proposals where project_id=p_project_id;
 insert into public.consult_proposals(project_id,user_id,title,version,status,valid_until,storage_path,original_filename,mime_type)
 values(p_project_id,v_owner,trim(p_title),v_version,'sent',p_valid_until,p_storage_path,p_original_filename,p_mime_type)
 returning id into v_id;
 insert into public.consult_documents(project_id,proposal_id,owner_id,category,title,storage_path,original_filename,mime_type,version)
 values(p_project_id,v_id,v_owner,'proposal',trim(p_title),p_storage_path,p_original_filename,p_mime_type,v_version);
 return v_id;
end $function$;

-- Reconnect unaccepted proposals created on a duplicate of the same request.
-- Keep document storage, owner and historical projects; never alter accepted SOWs.
do $$ declare s record; target uuid; candidates integer; next_version integer;
begin
 for s in select pr.id,pr.project_id,pr.user_id,p.request_id from public.consult_proposals pr
 join public.consult_projects p on p.id=pr.project_id
 where pr.status='sent' and p.request_id is not null
 and not exists(select 1 from public.consult_invoices i where i.proposal_id=pr.id)
 and not exists(select 1 from public.consult_quotations q where q.project_id=p.id and q.status='accepted')
 loop
   select count(*),(array_agg(p.id))[1] into candidates,target from public.consult_projects p
   where p.request_id=s.request_id and p.user_id=s.user_id and p.id<>s.project_id
   and exists(select 1 from public.consult_quotations q where q.project_id=p.id and q.status='accepted' and q.amount>0)
   and not exists(select 1 from public.consult_proposals pr where pr.project_id=p.id);
   if candidates<>1 then continue; end if;
   perform 1 from public.consult_projects where id=target for update;
   select coalesce(max(version),0)+1 into next_version from public.consult_proposals where project_id=target;
   update public.consult_proposals set project_id=target,version=next_version,updated_at=now() where id=s.id and status='sent';
   update public.consult_documents set project_id=target,version=next_version where proposal_id=s.id;
   insert into public.audit_logs(action,product,target_type,target_id,metadata) values
   ('consult_proposal_duplicate_project_relinked','consult','consult_proposal',s.id::text,
     jsonb_build_object('previous_project_id',s.project_id,'project_id',target,'request_id',s.request_id,'reason','Same request and owner; unique accepted-quotation project'));
 end loop;
end $$;

create or replace function public.manage_consult_milestone(p_project uuid,p_action text,p_record uuid default null,p_title text default null,p_description text default null,p_due date default null)
returns uuid language plpgsql security definer set search_path=public,pg_temp as $$
declare result uuid; old_state text;
begin
 if auth.uid() is null or not coalesce(private.has_product_access('consult','edit'),false) then raise exception 'Consult edit access required'; end if;
 perform 1 from public.consult_projects where id=p_project for update;
 if not found then raise exception 'Project not found'; end if;
 if p_action='create' then
   if length(trim(coalesce(p_title,'')))<3 then raise exception 'Milestone title required'; end if;
   insert into public.consult_milestones(project_id,title,description,due_at,sort_order,status)
   select p_project,trim(p_title),p_description,p_due,coalesce(max(sort_order),0)+10,'pending' from public.consult_milestones where project_id=p_project returning id into result;
 elsif p_action in ('start','complete') then
   select id,status into result,old_state from public.consult_milestones where id=p_record and project_id=p_project for update;
   if result is null then raise exception 'Milestone not found'; end if;
   if old_state='completed' then return result; end if;
   if p_action='complete' and old_state<>'in_progress' then raise exception 'Start this milestone before completing it'; end if;
   update public.consult_milestones set status=case when p_action='start' then 'in_progress' else 'completed' end,updated_at=now() where id=result;
 else raise exception 'Unsupported milestone action'; end if;
 update public.consult_projects set progress=(select round(100.0*count(*) filter(where status='completed')/greatest(count(*),1))::integer from public.consult_milestones where project_id=p_project),updated_at=now() where id=p_project;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'consult_milestone_'||p_action,'consult','consult_milestone',result::text,jsonb_build_object('project_id',p_project));
 return result;
end $$;
