create or replace function public.prepare_service_invoice_payment(p_platform text,p_user uuid,p_invoice uuid,p_account uuid)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare inv record; parent record; account public.virtual_accounts; intent jsonb;
  due numeric; owner uuid; link_column text; parent_table text;
begin
 if p_platform is null or p_platform not in ('consult','engineering','print','host') then raise exception 'Unsupported payment platform'; end if;
 if p_user is null or not exists(select 1 from public.profiles where id=p_user and status='active') then raise exception 'Active account required'; end if;
 execute format('select *,%s as payment_balance from public.%I where id=$1 for update',
   case when p_platform='host' then '0::numeric' else 'amount_paid' end,p_platform||'_invoices') into inv using p_invoice;
 if inv.id is null then raise exception 'Invoice not found'; end if;
 if p_platform in ('consult','engineering') then
   link_column:='project_id';parent_table:=p_platform||'_projects';
 else link_column:='order_id';parent_table:=p_platform||'_orders'; end if;
 execute format('select * from public.%I where id=$1',parent_table) into parent using (to_jsonb(inv)->>link_column)::uuid;
 if parent.id is null or parent.user_id is distinct from p_user then raise exception 'Invoice owner mismatch'; end if;
 if inv.status is null or inv.status not in ('issued','unpaid','part_paid','overdue','awaiting_payment') then raise exception 'Invoice is not payable'; end if;
 if inv.currency is distinct from 'NGN' then raise exception 'Invoice currency must be NGN'; end if;
 due:=inv.amount-coalesce(inv.payment_balance,0);
 if due is null or due<=0 or due<>round(due,2) then raise exception 'Invalid invoice balance'; end if;
 if p_platform='host' then
   if parent.status<>'awaiting_payment' or parent.payment_status='paid' or parent.amount<>inv.amount then raise exception 'Hosting order is not ready for payment'; end if;
 end if;
 select * into account from public.virtual_accounts where id=p_account and user_id=p_user and platform_code=p_platform and provider='billstack' and status='active';
 if account.id is null or nullif(trim(account.account_number),'') is null or nullif(trim(account.bank_name),'') is null or nullif(trim(account.account_name),'') is null then raise exception 'Active platform payment account required'; end if;
 execute format('select to_jsonb(i) from public.%I i where invoice_id=$1 and status=''pending'' order by created_at limit 1',p_platform||'_payment_intents') into intent using p_invoice;
 if intent is not null then
   if (intent->>'amount')::numeric<>due or (intent->>'virtual_account_id')::uuid<>p_account or (intent->>'user_id')::uuid<>p_user then raise exception 'Existing payment instruction requires reconciliation before replacement'; end if;
   return intent;
 end if;
 execute format('insert into public.%I(user_id,%I,invoice_id,virtual_account_id,amount,reference) values($1,$2,$3,$4,$5,$6) returning to_jsonb(%I)',p_platform||'_payment_intents',link_column,p_platform||'_payment_intents') into intent
 using p_user,(to_jsonb(inv)->>link_column)::uuid,p_invoice,p_account,due,upper(p_platform)||'-'||replace(gen_random_uuid()::text,'-','');
 return intent;
end $$;
