create or replace function private.issue_business_invoice(p_order uuid,p_due_at date default null)
returns uuid language plpgsql security definer set search_path='' as $$
declare o public.business_orders%rowtype; q public.business_quotes%rowtype; i uuid;
begin
 select * into o from public.business_orders where id=p_order for update;
 if not found then raise exception 'Order not found'; end if;
 select id into i from public.business_invoices where order_id=o.id and status<>'cancelled';
 if i is not null then return i; end if;
 if (select count(*) from public.business_quotes where order_id=o.id and status='accepted')<>1 then raise exception 'One accepted quote is required'; end if;
 select * into q from public.business_quotes where order_id=o.id and status='accepted' for update;
 if q.amount is null or q.amount<=0 or q.amount<>round(q.amount,2) or q.currency<>'NGN' then raise exception 'Accepted quote must have a positive NGN amount'; end if;
 insert into public.business_invoices(order_id,quotation_id,amount,amount_paid,currency,status,due_at)
 values(o.id,q.id,q.amount,0,q.currency,'issued',p_due_at) returning id into i;
 update public.business_orders set amount=q.amount,currency=q.currency,status='awaiting_payment',updated_at=now() where id=o.id;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'business_invoice_issued',o.unit_code,'business_invoice',i::text,jsonb_build_object('order_id',o.id,'quotation_id',q.id,'amount',q.amount));
 return i;
end $$;
