create or replace function public.respond_business_quote(p_quote uuid,p_response text)
returns void language plpgsql security definer set search_path='' as $$
declare q public.business_quotes%rowtype; o public.business_orders%rowtype; oid uuid;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if p_response is null or p_response not in ('accepted','revision_requested','rejected') then raise exception 'Invalid quote response'; end if;
 select order_id into oid from public.business_quotes where id=p_quote;
 if not found then raise exception 'Quote not found'; end if;
 select * into o from public.business_orders where id=oid for update;
 if o.user_id is distinct from auth.uid() then raise exception 'Quote does not belong to this customer'; end if;
 select * into q from public.business_quotes where id=p_quote for update;
 if q.status=p_response then
  if p_response='accepted' then perform private.issue_business_invoice(o.id); end if;
  return;
 end if;
 if q.status<>'issued' then raise exception 'Issued quote unavailable'; end if;
 if q.valid_until is not null and q.valid_until<current_date then raise exception 'Quote has expired'; end if;
 if p_response='accepted' then
  if q.amount is null or q.amount<=0 or q.amount<>round(q.amount,2) or q.currency<>'NGN' then raise exception 'Quote must have a positive NGN amount'; end if;
  if exists(select 1 from public.business_quotes where order_id=o.id and status='accepted' and id<>q.id) then raise exception 'This order already has an accepted quote'; end if;
  if exists(select 1 from public.business_invoices where order_id=o.id and status<>'cancelled') then raise exception 'This order already has an invoice'; end if;
 end if;
 update public.business_quotes set status=p_response,updated_at=now() where id=q.id;
 if p_response='accepted' then perform private.issue_business_invoice(o.id);
 else update public.business_orders set status=case p_response when 'revision_requested' then 'reviewing' else 'cancelled' end,updated_at=now() where id=o.id; end if;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'business_quote_'||p_response,o.unit_code,'business_quote',q.id::text,jsonb_build_object('order_id',o.id));
end $$;
