create or replace function private.schoolpro_record_school(p_table text,p_row jsonb)
returns uuid language plpgsql stable security definer set search_path='' as $$
declare parent_table text; parent_column text; parent_row jsonb;
begin
 if p_row ? 'school_id' then return nullif(p_row->>'school_id','')::uuid; end if;
 case p_table
 when 'schoolpro_admission_acceptances','schoolpro_admission_documents','schoolpro_admission_events','schoolpro_admission_offers' then parent_table:='schoolpro_admissions';parent_column:='application_id';
 when 'schoolpro_assignment_submissions' then parent_table:='schoolpro_assignments';parent_column:='assignment_id';
 when 'schoolpro_candidate_cbt_attempts','schoolpro_cbt_attempts','schoolpro_cbt_test_questions' then parent_table:='schoolpro_cbt_tests';parent_column:='test_id';
 when 'schoolpro_candidate_cbt_answers' then parent_table:='schoolpro_candidate_cbt_attempts';parent_column:='attempt_id';
 when 'schoolpro_cbt_answers' then parent_table:='schoolpro_cbt_attempts';parent_column:='attempt_id';
 when 'schoolpro_fee_items' then parent_table:='schoolpro_fee_structures';parent_column:='fee_structure_id';
 else return null;
 end case;
 if nullif(p_row->>parent_column,'') is null then return null; end if;
 execute format('select to_jsonb(t) from public.%I t where id=$1',parent_table) into parent_row using (p_row->>parent_column)::uuid;
 return private.schoolpro_record_school(parent_table,parent_row);
end $$;
revoke all on function private.schoolpro_record_school(text,jsonb) from public;
grant execute on function private.schoolpro_record_school(text,jsonb) to authenticated,anon,service_role;

create or replace function private.guard_schoolpro_operational_write()
returns trigger language plpgsql security definer set search_path='' as $$
declare old_school uuid; new_school uuid;
begin
 -- Trusted background settlement/maintenance can still update historic records.
 if auth.uid() is null and coalesce(current_setting('request.jwt.claim.role',true),'')<>'anon' then
  if tg_op='DELETE' then return old; else return new; end if;
 end if;
 if tg_op<>'INSERT' then old_school:=private.schoolpro_record_school(tg_table_name,to_jsonb(old)); end if;
 if tg_op<>'DELETE' then new_school:=private.schoolpro_record_school(tg_table_name,to_jsonb(new)); end if;
 if (old_school is not null and not private.schoolpro_operationally_active(old_school))
 or (new_school is not null and not private.schoolpro_operationally_active(new_school)) then
  raise exception 'SchoolPro operational activation required: complete subscription payment or an audited Control Center activation';
 end if;
 if old_school is null and new_school is null and not coalesce(private.has_product_access('schoolpro','edit'),false) then raise exception 'School-linked operational record required'; end if;
 if tg_op='DELETE' then return old; else return new; end if;
end $$;
revoke all on function private.guard_schoolpro_operational_write() from public,anon,authenticated;

-- Apply to school-owned operations and explicit child relationships, excluding billing/onboarding/identity.
do $$
declare r record; predicate text;
begin
 for r in select c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace
 where n.nspname='public' and c.relkind='r' and c.relname like 'schoolpro_%'
 and c.relname not in ('schoolpro_schools','schoolpro_members','schoolpro_member_permissions','schoolpro_guardian_links',
 'schoolpro_audit_logs','schoolpro_notifications','schoolpro_email_queue','schoolpro_custom_requests','schoolpro_demo_requests',
 'schoolpro_feature_overrides','schoolpro_subscriptions','schoolpro_subscription_catalog','schoolpro_subscription_plans',
 'schoolpro_subscription_intents','schoolpro_subscription_payments','schoolpro_plan_catalog','schoolpro_onboarding_requests')
 and (exists(select 1 from pg_attribute a where a.attrelid=c.oid and a.attname='school_id' and not a.attisdropped)
 or c.relname in ('schoolpro_admission_acceptances','schoolpro_admission_documents','schoolpro_admission_events','schoolpro_admission_offers',
 'schoolpro_assignment_submissions','schoolpro_candidate_cbt_attempts','schoolpro_candidate_cbt_answers','schoolpro_cbt_attempts',
 'schoolpro_cbt_answers','schoolpro_cbt_test_questions','schoolpro_fee_items'))
 loop
  execute format('drop trigger if exists schoolpro_activation_before_write on public.%I',r.relname);
  execute format('create trigger schoolpro_activation_before_write before insert or update or delete on public.%I for each row execute function private.guard_schoolpro_operational_write()',r.relname);
 end loop;
end $$;

