create or replace function public.issue_engineering_proposal(p_project uuid,p_title text,p_scope text,p_amount numeric,p_valid_until date default null)
returns uuid language plpgsql security definer set search_path='' as $$
declare i uuid;
begin
 if auth.uid() is null or not coalesce(private.has_product_access('engineering','edit'),false) then raise exception 'Engineering edit access required'; end if;
 if nullif(trim(p_title),'') is null or nullif(trim(p_scope),'') is null or p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) then raise exception 'Title, scope and positive exact proposal amount required'; end if;
 if p_valid_until is not null and p_valid_until<current_date then raise exception 'Proposal validity cannot be in the past'; end if;
 perform 1 from public.engineering_projects where id=p_project for update;
 if not found then raise exception 'Project not found'; end if;
 if exists(select 1 from public.engineering_proposals where project_id=p_project and status='accepted') then raise exception 'Project already has an accepted commercial proposal'; end if;
 insert into public.engineering_proposals(project_id,title,scope,amount,currency,status,valid_until)
 values(p_project,trim(p_title),trim(p_scope),p_amount,'NGN','sent',p_valid_until) returning id into i;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'engineering_proposal_issued','engineering','engineering_proposal',i::text,jsonb_build_object('project_id',p_project,'amount',p_amount));
 return i;
end $$;
revoke all on function public.issue_engineering_proposal(uuid,text,text,numeric,date) from public,anon;
grant execute on function public.issue_engineering_proposal(uuid,text,text,numeric,date) to authenticated;

create or replace function public.respond_engineering_proposal(p_proposal uuid,p_response text)
returns uuid language plpgsql security definer set search_path='' as $$
declare q public.engineering_proposals%rowtype; p public.engineering_projects%rowtype; pid uuid; i uuid;
begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) then raise exception 'Active authenticated account required'; end if;
 if p_response is null or p_response not in ('accepted','revision_requested','rejected') then raise exception 'Invalid proposal response'; end if;
 select project_id into pid from public.engineering_proposals where id=p_proposal;
 if not found then raise exception 'Proposal not found'; end if;
 select * into p from public.engineering_projects where id=pid for update;
 if p.user_id is distinct from auth.uid() then raise exception 'Only the project owner can respond'; end if;
 select * into q from public.engineering_proposals where id=p_proposal for update;
 if q.status=p_response then
  if p_response='accepted' then
   select id into i from public.engineering_invoices where proposal_id=q.id and status<>'cancelled';
   if i is not null then return i; end if;
  else return null; end if;
 elsif q.status<>'sent' then raise exception 'Sent proposal required';
 end if;
 if p_response='accepted' then
  if q.valid_until is not null and q.valid_until<current_date and q.status<>'accepted' then raise exception 'Proposal has expired'; end if;
  if q.amount is null or q.amount<=0 or q.amount<>round(q.amount,2) or q.currency<>'NGN' then raise exception 'Positive NGN proposal amount required'; end if;
  if exists(select 1 from public.engineering_proposals where project_id=p.id and status='accepted' and id<>q.id) then raise exception 'Another proposal is already accepted'; end if;
  if exists(select 1 from public.engineering_invoices where project_id=p.id and proposal_id is null and status<>'cancelled') then raise exception 'Existing project invoice requires commercial reconciliation before accepting another proposal'; end if;
  update public.engineering_proposals set status='accepted',updated_at=now() where id=q.id;
  insert into public.engineering_invoices(project_id,proposal_id,title,amount,amount_paid,currency,status)
  values(p.id,q.id,q.title,q.amount,0,q.currency,'issued') returning id into i;
 else update public.engineering_proposals set status=p_response,updated_at=now() where id=q.id;
 end if;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'engineering_proposal_'||p_response,'engineering','engineering_proposal',q.id::text,jsonb_build_object('project_id',p.id,'invoice_id',i));
 return i;
end $$;
revoke all on function public.respond_engineering_proposal(uuid,text) from public,anon;
grant execute on function public.respond_engineering_proposal(uuid,text) to authenticated;
revoke insert,update,delete on public.engineering_invoices,public.engineering_proposals from authenticated,anon;

create or replace function public.manage_host_order(p_order uuid,p_action text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare o public.host_orders%rowtype;
begin
 if auth.uid() is null or not coalesce(public.host_can_provision(),false) then raise exception 'Host provisioning access required'; end if;
 select * into o from public.host_orders where id=p_order for update;
 if not found then raise exception 'Order not found'; end if;
 if p_action='start' then
  if o.payment_status<>'paid' or o.status not in ('paid','provisioning') or not exists(select 1 from public.host_invoices where order_id=o.id and status='paid' and amount=o.amount and paid_at is not null and nullif(payment_reference,'') is not null) then raise exception 'Settled invoice required before provisioning'; end if;
  if o.status='provisioning' then return jsonb_build_object('status','provisioning','order_id',o.id); end if;
  update public.host_orders set status='provisioning',provisioning_status='in_progress',updated_at=now() where id=o.id;
 elsif p_action='reject' then
  if o.status='rejected' then return jsonb_build_object('status','rejected','order_id',o.id); end if;
  if o.status not in ('pending_review','awaiting_payment') or o.payment_status='paid' then raise exception 'Only unsettled orders can be rejected'; end if;
  if exists(select 1 from public.host_payment_intents where order_id=o.id and status='pending') then raise exception 'Pending payment instruction requires reconciliation before rejection'; end if;
  update public.host_orders set status='rejected',updated_at=now() where id=o.id;
  update public.host_invoices set status='cancelled',updated_at=now() where order_id=o.id and status in ('draft','unpaid','issued','awaiting_payment');
 else raise exception 'Invalid order action'; end if;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'host_order_'||p_action,'host','host_order',o.id::text,jsonb_build_object('previous_status',o.status));
 return jsonb_build_object('status',case p_action when 'start' then 'provisioning' else 'rejected' end,'order_id',o.id);
end $$;
revoke all on function public.manage_host_order(uuid,text) from public,anon;
grant execute on function public.manage_host_order(uuid,text) to authenticated;

create or replace function public.complete_host_provisioning(p_order uuid,p_provider_reference text,p_control_panel_url text default null,p_nameservers jsonb default '[]'::jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare o public.host_orders%rowtype; s public.host_services%rowtype; stype text; sname text;
begin
 if auth.uid() is null or not coalesce(public.host_can_provision(),false) then raise exception 'Host provisioning access required'; end if;
 if nullif(trim(p_provider_reference),'') is null or length(trim(p_provider_reference))>200 or p_provider_reference ~* '(SMARTWEB-PENDING|^pending|^mock|^demo|^placeholder)' then raise exception 'Confirmed upstream provider reference required'; end if;
 if p_control_panel_url is not null and p_control_panel_url !~ '^https://' then raise exception 'Control panel must use HTTPS'; end if;
 if p_nameservers is null or jsonb_typeof(p_nameservers)<>'array' then raise exception 'Nameservers must be a JSON array'; end if;
 select * into o from public.host_orders where id=p_order for update;
 if not found or o.payment_status<>'paid' or not exists(select 1 from public.host_invoices where order_id=o.id and status='paid' and amount=o.amount and paid_at is not null and nullif(payment_reference,'') is not null) then raise exception 'Settled invoice required before activation'; end if;
 if o.status='active' then
  if o.provider_reference is distinct from trim(p_provider_reference) then raise exception 'Order already activated with another provider reference'; end if;
  select * into s from public.host_services where id=o.renewal_service_id or (o.renewal_service_id is null and order_id=o.id) limit 1;
  if s.id is null then raise exception 'Active order has no service; reconciliation required'; end if;
  return jsonb_build_object('status','active','service_id',s.id);
 end if;
 if o.status not in ('paid','provisioning') then raise exception 'Order is not ready for activation'; end if;
 if o.renewal_service_id is not null then
  update public.host_services set status='active',provider_reference=trim(p_provider_reference),renews_at=greatest(coalesce(renews_at,current_date),current_date)+(o.billing_cycle_months||' months')::interval,updated_at=now()
  where id=o.renewal_service_id and user_id=o.user_id returning * into s;
  if not found then raise exception 'Renewal service ownership mismatch'; end if;
 else
  if exists(select 1 from public.host_services where order_id=o.id) then raise exception 'Existing service requires reconciliation'; end if;
  stype:=case when o.order_type='domain_registration' then 'domain' else o.order_type end;
  sname:=case when stype='domain' then coalesce(o.domain_name,'Domain') else initcap(replace(stype,'_',' ')) end;
  insert into public.host_services(user_id,order_id,service_type,service_name,domain_name,status,provider_reference,control_panel_url,nameservers,activated_at,renews_at)
  values(o.user_id,o.id,stype,sname,o.domain_name,'active',trim(p_provider_reference),p_control_panel_url,p_nameservers,now(),current_date+(o.billing_cycle_months||' months')::interval) returning * into s;
 end if;
 update public.host_orders set status='active',provisioning_status='completed',provider_reference=trim(p_provider_reference),updated_at=now() where id=o.id;
 update public.host_provisioning_jobs set status='completed',updated_at=now() where order_id=o.id;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'host_upstream_activation_confirmed','host','host_order',o.id::text,jsonb_build_object('provider_reference',trim(p_provider_reference),'service_id',s.id,'confirmation_source','authorized_operator'));
 return jsonb_build_object('status','active','service_id',s.id);
end $$;
revoke all on function public.complete_host_provisioning(uuid,text,text,jsonb) from public,anon;
grant execute on function public.complete_host_provisioning(uuid,text,text,jsonb) to authenticated;
revoke insert,update,delete on public.host_orders,public.host_invoices,public.host_services from authenticated,anon;
CREATE OR REPLACE FUNCTION public.approve_host_domain_for_payment(p_order uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.host_orders%rowtype;begin if auth.uid() is null or not coalesce(public.host_can_provision(),false) then raise exception 'Permission denied';end if;select * into o from public.host_orders where id=p_order for update;if o.id is null or o.order_type<>'domain_registration' or o.status<>'pending_review' then raise exception 'Domain order is not awaiting availability review';end if;update public.host_orders set status='awaiting_payment',updated_at=now() where id=o.id;update public.host_invoices set status='unpaid',updated_at=now() where order_id=o.id;return jsonb_build_object('status','awaiting_payment','order_id',o.id);end $function$;

CREATE OR REPLACE FUNCTION public.finalize_host_billstack_payment(p_intent uuid, p_transaction_ref text, p_amount numeric, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i public.host_payment_intents;o public.host_orders;tx public.payment_transactions;pid uuid;act text;provisioning_provider text;
begin
 if p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) or nullif(btrim(p_transaction_ref),'') is null then raise exception 'Verified exact payment required';end if;
 select * into i from public.host_payment_intents where id=p_intent for update;if i.id is null then raise exception 'Host payment intent not found';end if;
 if i.status='paid' then if i.transaction_ref=p_transaction_ref and i.amount=p_amount then return jsonb_build_object('status','already_paid','order_id',i.order_id);end if;raise exception 'Intent already settled by another transaction';end if;
 select * into tx from public.payment_transactions where provider='billstack' and transaction_ref=p_transaction_ref for update;
 if i.status<>'pending' or i.amount is distinct from p_amount or tx.id is null or tx.status not in('verified','credited') or tx.credited_at is not null or tx.amount<>p_amount or tx.currency<>'NGN' or tx.user_id is distinct from i.user_id or tx.platform_code is distinct from 'host' or tx.virtual_account_id is distinct from i.virtual_account_id then raise exception 'Verified transaction ownership, platform or replay validation failed';end if;
 select * into o from public.host_orders where id=i.order_id for update;
 if o.id is null or o.user_id<>i.user_id or o.amount<>p_amount or o.status<>'awaiting_payment' or o.payment_status='paid' or not exists(select 1 from public.host_invoices v where v.id=i.invoice_id and v.order_id=i.order_id and v.user_id=i.user_id and v.amount=p_amount and v.currency='NGN' and v.status in ('unpaid','issued','awaiting_payment','overdue')) then raise exception 'Host invoice/order linkage mismatch';end if;
 if exists(select 1 from public.host_payments where transaction_ref=p_transaction_ref) then raise exception 'Payment reference already processed';end if;
 insert into public.host_payments(user_id,invoice_id,amount,currency,provider_reference,status,paid_at,virtual_account_id,transaction_ref,verified_at,provider_payload) values(i.user_id,i.invoice_id,p_amount,'NGN',p_transaction_ref,'verified',now(),i.virtual_account_id,p_transaction_ref,now(),p_payload) returning id into pid;
 update public.host_invoices set status='paid',paid_at=now(),payment_reference=p_transaction_ref,payment_id=pid,updated_at=now() where id=i.invoice_id;
 update public.host_orders set payment_status='paid',status='paid',provisioning_status='pending',paid_at=now(),updated_at=now() where id=i.order_id;
 update public.host_payment_intents set status='paid',transaction_ref=p_transaction_ref,paid_at=now(),updated_at=now() where id=i.id;
 update public.payment_transactions set status='credited',credited_at=now(),updated_at=now() where id=tx.id;
 act:=case when o.renewal_service_id is not null then 'renew' when o.order_type='domain_registration' then 'domain_register' else 'hosting_provision' end;
 provisioning_provider:=case when o.order_type='domain_registration' and o.domain_name like '%.ng' then 'nira' when o.order_type='domain_registration' then 'international_registrar' else 'cpanel_whm' end;
 insert into public.host_provisioning_jobs(order_id,user_id,action,provider_code,status) values(o.id,o.user_id,act,provisioning_provider,'queued') on conflict(order_id,action) do update set status=case when public.host_provisioning_jobs.status='completed' then 'completed' else 'queued' end,updated_at=now();
 return jsonb_build_object('status','paid','invoice_id',i.invoice_id,'order_id',i.order_id,'provisioning_status','queued');
end$function$;

