-- Store receipt evidence atomically with verified Print/Engineering settlement.
create table if not exists public.engineering_payments (
 id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.engineering_invoices(id),
 user_id uuid not null,payment_intent_id uuid unique references public.engineering_payment_intents(id),
 amount numeric not null check(amount>0 and amount=round(amount,2)),currency text not null default 'NGN' check(currency='NGN'),
 transaction_ref text not null unique,provider_reference text not null,provider text not null default 'billstack',
 status text not null default 'paid' check(status in ('paid','refunded')),paid_at timestamptz not null,created_at timestamptz not null default now()
