-- Specialist execution cannot bypass the settled commercial order through a child job write.
create or replace function private.business_order_payment_guard()
returns trigger language plpgsql security definer set search_path='' as $$
begin
 if new.status in ('paid','in_progress','running','production','completed','delivered')
 and (tg_op='INSERT' or new.status is distinct from old.status or new.amount is distinct from old.amount)
 and not exists(select 1 from public.business_invoices i where i.order_id=new.id and i.status='paid' and i.amount_paid=i.amount and i.amount>0 and i.amount=new.amount and i.currency=new.currency)
 then raise exception 'Verified invoice payment is required before fulfilment'; end if;
 return new;
end $$;
drop trigger if exists business_order_payment_guard on public.business_orders;
create trigger business_order_payment_guard before insert or update on public.business_orders for each row execute function private.business_order_payment_guard();

create or replace function private.guard_specialist_execution()
returns trigger language plpgsql security definer set search_path='' as $$
declare target_unit text;
begin
 if new.status not in ('in_progress','running','production','printing','completed','delivered') then return new; end if;
 if tg_op='UPDATE' and new.status is not distinct from old.status and new.order_id is not distinct from old.order_id then return new; end if;
 target_unit:=case tg_table_name when 'compute_jobs' then 'compute' else 'fabrication' end;
 if not exists(select 1 from public.business_orders o join public.business_invoices i on i.order_id=o.id
 where o.id=new.order_id and o.unit_code=target_unit and i.status='paid' and i.amount_paid=i.amount and i.amount>0 and i.amount=o.amount and i.currency=o.currency)
 then raise exception 'Verified invoice payment is required before specialist execution'; end if;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'specialist_execution_'||new.status,target_unit,tg_table_name,new.id::text,jsonb_build_object('order_id',new.order_id));
 return new;
end $$;
revoke all on function private.guard_specialist_execution() from public,anon,authenticated;
drop trigger if exists specialist_execution_payment_gate on public.fabrication_jobs;
create trigger specialist_execution_payment_gate before insert or update on public.fabrication_jobs for each row execute function private.guard_specialist_execution();
drop trigger if exists specialist_execution_payment_gate on public.compute_jobs;
create trigger specialist_execution_payment_gate before insert or update on public.compute_jobs for each row execute function private.guard_specialist_execution();

create or replace function private.guard_engineering_execution()
returns trigger language plpgsql security definer set search_path='' as $$
begin
 if (new.stage in ('procurement','installation','commissioning','completed') or new.status in ('commissioned','completed'))
 and (tg_op='INSERT' or new.stage is distinct from old.stage or new.status is distinct from old.status)
 then
  if not exists(select 1 from public.engineering_invoices i where i.project_id=new.id and i.status='paid' and i.amount_paid=i.amount and i.amount>0)
  or exists(select 1 from public.engineering_invoices i where i.project_id=new.id and i.status<>'cancelled' and (i.status<>'paid' or i.amount_paid<i.amount))
  then raise exception 'Settled project invoices are required before Engineering execution'; end if;
  insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
  values(auth.uid(),'engineering_execution_'||new.stage,'engineering','engineering_project',new.id::text,jsonb_build_object('stage',new.stage,'status',new.status));
 end if;
 return new;
end $$;
revoke all on function private.guard_engineering_execution() from public,anon,authenticated;
drop trigger if exists engineering_execution_payment_gate on public.engineering_projects;
create trigger engineering_execution_payment_gate before insert or update on public.engineering_projects for each row execute function private.guard_engineering_execution();

CREATE OR REPLACE FUNCTION public.print_record_qc(p_job uuid, p_passed boolean, p_notes text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j public.print_jobs; q uuid;
begin
 if auth.uid() is null or not coalesce(private.print_staff_permission('edit'),false) then raise exception 'Print edit permission required'; end if;
 select * into j from public.print_jobs where id=p_job for update;
 if not found or j.stage<>'qc' then raise exception 'Job must be at quality control'; end if;
 if p_passed is null or (not p_passed and nullif(trim(p_notes),'') is null) then raise exception 'Record a result and defect notes for failed QC'; end if;
 if not exists(select 1 from public.print_invoices where order_id=j.order_id and status='paid' and amount_paid=amount and amount>0) then raise exception 'Verified payment required'; end if;
 insert into public.print_qc_checks(job_id,status,defect_notes,reprint_required,checked_by) values(j.id,case when p_passed then 'passed' else 'failed' end,p_notes,not p_passed,auth.uid()) returning id into q;
 if not p_passed then update public.print_jobs set stage='production',progress=40 where id=j.id; end if;
 insert into public.print_audit_logs(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'quality_checked','job',j.id,jsonb_build_object('passed',p_passed,'notes',p_notes));
 return q;
end $function$;
CREATE OR REPLACE FUNCTION public.print_advance_job(p_order uuid, p_stage text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.print_orders; j public.print_jobs; stages text[]:=array['prepress','production','finishing','qc','ready']; next_index int; old_index int;
begin
 if auth.uid() is null or not coalesce(private.print_staff_permission('edit'),false) then raise exception 'Print edit permission required'; end if;
 select * into o from public.print_orders where id=p_order for update;
 if not found then raise exception 'Order not found'; end if;
 if not exists(select 1 from public.print_invoices where order_id=o.id and status='paid' and amount_paid=amount and amount>0) then raise exception 'Verified full invoice payment is required before production'; end if;
 if coalesce((select status from public.print_proofs where order_id=o.id order by created_at desc,version desc limit 1),'')<>'approved' then raise exception 'Customer-approved proof required before production'; end if;
 next_index:=array_position(stages,p_stage);
 if next_index is null then raise exception 'Invalid production stage'; end if;
 select * into j from public.print_jobs where order_id=o.id order by created_at desc limit 1 for update;
 old_index:=coalesce(array_position(stages,j.stage),0);
 if next_index<>old_index+1 then raise exception 'Advance one production stage at a time'; end if;
 if p_stage='ready' and coalesce((select status='passed' and not reprint_required from public.print_qc_checks where job_id=j.id order by created_at desc limit 1),false)=false then raise exception 'Passed quality control is required'; end if;
 if j.id is null then insert into public.print_jobs(order_id,stage,progress,internal_notes,started_at) values(o.id,p_stage,20,p_notes,now()) returning * into j;
 else update public.print_jobs set stage=p_stage,progress=next_index*20,internal_notes=p_notes,completed_at=case when p_stage='ready' then now() else null end where id=j.id; end if;
 update public.print_orders set status=case when p_stage='ready' then 'ready' else 'in_production' end where id=o.id;
 insert into public.print_audit_logs(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'production_advanced','job',j.id,jsonb_build_object('stage',p_stage,'notes',p_notes));
 return j.id;
end $function$;
CREATE OR REPLACE FUNCTION public.print_dispatch_order(p_order uuid, p_status text, p_recipient text, p_tracking text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.print_orders; d public.print_deliveries;
begin
 if auth.uid() is null or not coalesce(private.print_staff_permission('edit'),false) then raise exception 'Print edit permission required'; end if;
 select * into o from public.print_orders where id=p_order for update;
 if not found or o.status not in ('ready','dispatched') or p_status is null or p_status not in ('dispatched','delivered','collected') or nullif(trim(p_recipient),'') is null then raise exception 'Ready order and recipient required'; end if;
 if not exists(select 1 from public.print_invoices where order_id=o.id and status='paid' and amount_paid=amount and amount>0) then raise exception 'Verified payment required'; end if;
 if not exists(select 1 from public.print_jobs j join public.print_qc_checks q on q.job_id=j.id where j.order_id=o.id and j.stage='ready' and q.status='passed' and not q.reprint_required) then raise exception 'Completed production and passed QC required'; end if;
 if o.fulfillment='pickup' and p_status<>'collected' or o.fulfillment='delivery' and p_status='collected' then raise exception 'Use the configured fulfillment method'; end if;
 select * into d from public.print_deliveries where order_id=o.id order by created_at desc limit 1 for update;
 if p_status='delivered' and (d.id is null or d.status<>'dispatched') then raise exception 'Dispatch the order before confirming delivery'; end if;
 if d.id is null then insert into public.print_deliveries(order_id,method,address,status,tracking_reference,recipient_name,delivered_at) values(o.id,o.fulfillment,o.delivery_address,p_status,p_tracking,p_recipient,case when p_status in ('delivered','collected') then now() end) returning * into d;
 else update public.print_deliveries set status=p_status,tracking_reference=p_tracking,recipient_name=p_recipient,delivered_at=case when p_status in ('delivered','collected') then now() end where id=d.id; end if;
 update public.print_orders set status=case when p_status='dispatched' then 'dispatched' else 'completed' end where id=o.id;
 insert into public.print_notifications(user_id,order_id,title,body,kind) values(o.user_id,o.id,'Fulfilment updated',p_status||coalesce(' — '||p_tracking,''),'delivery');
 insert into public.print_audit_logs(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'fulfilment_updated','order',o.id,jsonb_build_object('status',p_status,'recipient',p_recipient));
 return d.id;
end $function$;
CREATE OR REPLACE FUNCTION public.print_issue_artwork_proof(p_artwork uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.print_artworks; proof uuid; version_no int;
begin
 if auth.uid() is null or not coalesce(private.print_staff_permission('edit'),false) then raise exception 'Print edit permission required'; end if;
 select * into a from public.print_artworks where id=p_artwork for update;
 if not found or nullif(a.file_path,'') is null then raise exception 'Artwork file required'; end if;
 perform 1 from public.print_orders where id=a.order_id for update;
 select coalesce(max(version),0)+1 into version_no from public.print_proofs where order_id=a.order_id;
 update public.print_proofs set status='superseded' where order_id=a.order_id and status='pending';
 insert into public.print_proofs(order_id,artwork_id,file_path,version,status) values(a.order_id,a.id,a.file_path,version_no,'pending') returning id into proof;
 insert into public.print_notifications(user_id,order_id,title,body,kind) values(a.user_id,a.order_id,'Proof ready for review','Review the supplied artwork and approve it or request a revision.','proof');
 insert into public.print_audit_logs(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'proof_issued','proof',proof,jsonb_build_object('artwork_id',a.id));
 return proof;
end $function$;
create or replace function public.respond_print_proof(p_proof uuid,p_response text,p_notes text default null)
returns uuid language plpgsql security definer set search_path='' as $$
declare p public.print_proofs%rowtype; o public.print_orders%rowtype; oid uuid;
begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) then raise exception 'Active authenticated account required'; end if;
 if p_response is null or p_response not in ('approved','revision_requested') then raise exception 'Invalid proof response'; end if;
 if p_response='revision_requested' and nullif(trim(p_notes),'') is null then raise exception 'Revision notes required'; end if;
 select order_id into oid from public.print_proofs where id=p_proof;
 select * into o from public.print_orders where id=oid for update;
 if o.user_id is distinct from auth.uid() then raise exception 'Only the order owner can respond'; end if;
 select * into p from public.print_proofs where id=p_proof for update;
 if not found then raise exception 'Proof not found'; end if;
 if p.status=p_response then return p.id; end if;
 if p.status<>'pending' then raise exception 'Pending proof required'; end if;
 update public.print_proofs set status=p_response,customer_notes=nullif(trim(p_notes),''),approved_at=case when p_response='approved' then now() else null end where id=p.id;
 insert into public.print_audit_logs(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'customer_proof_'||p_response,'proof',p.id,jsonb_build_object('order_id',o.id));
 return p.id;
end $$;
