CREATE OR REPLACE FUNCTION public.submit_direct_bank_transfer(p_platform text, p_invoice uuid, p_source_reference text, p_amount numeric, p_sender_name text, p_sender_bank text, p_customer_reference text, p_transferred_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_proof_storage_path text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_bank uuid;v_id uuid;v_enabled boolean;v_owner uuid;v_total numeric;v_paid numeric:=0;v_unit text;v_balance numeric;invoice_table text;invoice_state text;invoice_currency text;
begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) then raise exception 'Authentication required';end if;
 if p_platform='datasub' then raise exception 'DataSub requires immediate automated payment and fulfilment';end if;
 if p_platform='schoolpro' then raise exception 'SchoolPro bank transfers must use the dedicated school payment submission workflow';end if;
 if p_platform not in('host','consult','engineering','print','fabrication','compute','academy','digital_business','business_centre')
 then raise exception 'Direct transfer is not available for this platform';end if;
 if p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) then raise exception 'Positive exact transfer amount required'; end if;
 if length(trim(coalesce(p_proof_storage_path,'')))=0 then raise exception 'Payment receipt/proof is required';end if;
 if p_proof_storage_path not like auth.uid()::text||'/%' or not exists(select 1 from storage.objects where bucket_id='direct-transfer-proofs' and name=p_proof_storage_path) then raise exception 'Saved customer-owned payment proof required'; end if;
 invoice_table:=case p_platform when 'consult' then 'consult_invoices' when 'engineering' then 'engineering_invoices' when 'print' then 'print_invoices' when 'host' then 'host_invoices' else 'business_invoices' end;
 execute format('select status,currency from public.%I where id=$1',invoice_table) into invoice_state,invoice_currency using p_invoice;
 if invoice_state is null or invoice_state not in ('issued','unpaid','part_paid','overdue','awaiting_payment') or invoice_currency<>'NGN' then raise exception 'Payable NGN invoice required'; end if;
 select direct_bank_transfer_enabled into v_enabled from public.payment_platform_settings where platform_code=p_platform;
 if not coalesce(v_enabled,false) then raise exception 'Direct bank transfer is not enabled for this platform';end if;
 if p_platform='consult' then
  select pr.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid from public.consult_invoices i join public.consult_projects pr on pr.id=i.project_id where i.id=p_invoice;
 elsif p_platform='engineering' then
  select pr.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid from public.engineering_invoices i join public.engineering_projects pr on pr.id=i.project_id where i.id=p_invoice;
 elsif p_platform='print' then
  select o.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid from public.print_invoices i join public.print_orders o on o.id=i.order_id where i.id=p_invoice;
 elsif p_platform='host' then
  select i.user_id,i.amount,case when i.status='paid' then i.amount else 0 end into v_owner,v_total,v_paid from public.host_invoices i where i.id=p_invoice;
 elsif p_platform in('fabrication','compute','academy','digital_business','business_centre') then
  select o.user_id,i.amount,coalesce(i.amount_paid,0),o.unit_code into v_owner,v_total,v_paid,v_unit from public.business_invoices i join public.business_orders o on o.id=i.order_id where i.id=p_invoice;
  if v_owner is not null and v_unit<>p_platform then raise exception 'Invoice does not belong to the selected platform';end if;
 end if;
 if v_owner is null or v_owner<>auth.uid() then raise exception 'Invoice not found or does not belong to this account';end if;
 v_balance:=greatest(coalesce(v_total,0)-coalesce(v_paid,0),0);
 if v_balance<=0 then raise exception 'Invoice has no outstanding balance';end if;
 if p_amount<>v_balance then raise exception 'Transfer amount must equal the outstanding invoice balance';end if;
 if nullif(trim(coalesce(p_sender_name,'')),'') is null or nullif(trim(coalesce(p_customer_reference,'')),'') is null then raise exception 'Sender name and transfer reference are required';end if;
 if exists(select 1 from public.direct_transfer_submissions d where d.user_id=auth.uid() and d.platform_code=p_platform and d.invoice_id=p_invoice and d.status in('awaiting_verification','pending')) then raise exception 'A transfer proof for this invoice is already awaiting verification';end if;
 select id into v_bank from public.ihlink_bank_accounts where is_active=true order by is_default desc,created_at asc limit 1;
 if v_bank is null then raise exception 'IHLink direct bank account has not been configured';end if;
 insert into public.direct_transfer_submissions(user_id,platform_code,invoice_id,source_reference,bank_account_id,amount,sender_name,sender_bank,customer_reference,transferred_at,proof_storage_path,status)
 values(auth.uid(),p_platform,p_invoice,p_source_reference,v_bank,v_balance,trim(p_sender_name),nullif(trim(p_sender_bank),''),trim(p_customer_reference),p_transferred_at,p_proof_storage_path,'awaiting_verification') returning id into v_id;
 return v_id;
end $function$;
CREATE OR REPLACE FUNCTION public.review_direct_bank_transfer(p_submission uuid, p_decision text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 s public.direct_transfer_submissions%rowtype; new_status text;
 v_owner uuid; v_total numeric; v_paid numeric:=0; v_unit text; v_balance numeric; v_rows int; invoice_table text; invoice_state text; invoice_currency text; receipt_ref text;
begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) then raise exception 'Authentication required'; end if;
 if p_decision is null or p_decision not in('approved','rejected') then raise exception 'Decision must be approved or rejected'; end if;

 select * into s from public.direct_transfer_submissions where id=p_submission for update;
 if s.id is null then raise exception 'Submission not found'; end if;
 if not coalesce((private.is_admin(array['super_admin'::public.user_role]) or private.business_staff_allowed(s.platform_code,'approve')),false)
   then raise exception 'Platform finance approval permission required'; end if;
 if length(trim(coalesce(p_note,'')))<3 then raise exception 'Finance verification or rejection note must contain at least 3 characters'; end if;
 if s.status=p_decision then return jsonb_build_object('id',s.id,'status',s.status,'platform',s.platform_code,'invoice_id',s.invoice_id); end if;
 if s.status not in('awaiting_verification','pending') then raise exception 'Submission has already been reviewed'; end if;

 if p_decision='approved' then
   if s.proof_storage_path is null or s.proof_storage_path not like s.user_id::text||'/%' or not exists(select 1 from storage.objects where bucket_id='direct-transfer-proofs' and name=s.proof_storage_path) then raise exception 'A saved customer-owned transfer proof is required'; end if;
   perform 1 from public.ihlink_bank_accounts where id=s.bank_account_id for update;
   if not found then raise exception 'Receiving bank account not found'; end if;
   if exists(select 1 from public.direct_transfer_submissions d where d.id<>s.id and d.status='approved' and d.bank_account_id=s.bank_account_id and lower(trim(d.customer_reference))=lower(trim(s.customer_reference))) then raise exception 'This bank transfer reference has already been reconciled'; end if;
   invoice_table:=case s.platform_code when 'consult' then 'consult_invoices' when 'engineering' then 'engineering_invoices' when 'print' then 'print_invoices' when 'host' then 'host_invoices' when 'fabrication' then 'business_invoices' when 'compute' then 'business_invoices' when 'academy' then 'business_invoices' when 'digital_business' then 'business_invoices' when 'business_centre' then 'business_invoices' end;
   if invoice_table is null then raise exception 'Unsupported direct-transfer platform'; end if;
   execute format('select status,currency from public.%I where id=$1 for update',invoice_table) into invoice_state,invoice_currency using s.invoice_id;
   if invoice_state is null or invoice_state not in ('issued','unpaid','part_paid','overdue','awaiting_payment') or invoice_currency<>'NGN' then raise exception 'Payable NGN invoice required'; end if;
   receipt_ref:='DIRECT-'||s.id::text;
   if s.platform_code='consult' then
     select pr.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid
     from public.consult_invoices i join public.consult_projects pr on pr.id=i.project_id where i.id=s.invoice_id for update of i;
   elsif s.platform_code='engineering' then
     select pr.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid
     from public.engineering_invoices i join public.engineering_projects pr on pr.id=i.project_id where i.id=s.invoice_id for update of i;
   elsif s.platform_code='print' then
     select o.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid
     from public.print_invoices i join public.print_orders o on o.id=i.order_id where i.id=s.invoice_id for update of i;
   elsif s.platform_code='host' then
     select i.user_id,i.amount,case when i.status='paid' then i.amount else 0 end into v_owner,v_total,v_paid
     from public.host_invoices i where i.id=s.invoice_id for update;
   elsif s.platform_code in('fabrication','compute','academy','digital_business','business_centre') then
     select o.user_id,i.amount,coalesce(i.amount_paid,0),o.unit_code into v_owner,v_total,v_paid,v_unit
     from public.business_invoices i join public.business_orders o on o.id=i.order_id where i.id=s.invoice_id for update of i;
     if v_owner is not null and v_unit<>s.platform_code then raise exception 'Submission platform does not match invoice platform'; end if;
   else
     raise exception 'Unsupported direct-transfer platform';
   end if;

   if v_owner is null or v_owner<>s.user_id then raise exception 'Transfer submission does not match invoice owner'; end if;
   v_balance:=greatest(coalesce(v_total,0)-coalesce(v_paid,0),0);
   if s.amount is null or s.amount<=0 or s.amount<>round(s.amount,2) then raise exception 'Positive exact transfer amount required'; end if;
   if v_balance<=0 then raise exception 'Invoice has already been settled'; end if;
   if s.amount<>v_balance then raise exception 'Transfer amount no longer matches the outstanding invoice balance'; end if;

   if s.platform_code='consult' then
     update public.consult_invoices set amount_paid=amount,status='paid',paid_at=now(),payment_reference=s.customer_reference,updated_at=now()
     where id=s.invoice_id;
   elsif s.platform_code='engineering' then
     update public.engineering_invoices set amount_paid=amount,status='paid',updated_at=now() where id=s.invoice_id;
   elsif s.platform_code='print' then
     update public.print_invoices set amount_paid=amount,status='paid',updated_at=now() where id=s.invoice_id;
   elsif s.platform_code='host' then
     update public.host_invoices set status='paid',paid_at=now(),payment_reference=s.customer_reference,updated_at=now() where id=s.invoice_id;
     update public.host_orders set payment_status='paid',paid_at=now(),status=case when status='awaiting_payment' then 'paid' else status end,updated_at=now()
     where id=(select order_id from public.host_invoices where id=s.invoice_id);
   else
     update public.business_invoices set amount_paid=amount,status='paid',updated_at=now() where id=s.invoice_id;
   end if;
   get diagnostics v_rows = row_count;
   if v_rows=0 then raise exception 'Invoice settlement failed'; end if;

   if s.platform_code='consult' then
    insert into public.consult_payments(project_id,payment_reference,amount,description,status,paid_at)
    select project_id,receipt_ref,s.amount,'Finance-verified direct bank transfer','paid',now() from public.consult_invoices where id=s.invoice_id;
    update public.consult_projects set outstanding_amount=(select coalesce(sum(greatest(amount-amount_paid,0)),0) from public.consult_invoices where project_id=public.consult_projects.id and status<>'cancelled'),updated_at=now() where id=(select project_id from public.consult_invoices where id=s.invoice_id);
   elsif s.platform_code='engineering' then
    insert into public.engineering_payments(invoice_id,user_id,amount,currency,transaction_ref,provider_reference,provider,status,paid_at)
    values(s.invoice_id,s.user_id,s.amount,'NGN',receipt_ref,receipt_ref,'direct_transfer','paid',now());
   elsif s.platform_code='print' then
    insert into public.print_payments(invoice_id,user_id,amount,currency,transaction_ref,provider_reference,provider,status,paid_at)
    values(s.invoice_id,s.user_id,s.amount,'NGN',receipt_ref,receipt_ref,'direct_transfer','paid',now());
    update public.print_orders set status=case when status in ('request','quoted','awaiting_payment') then 'artwork' else status end,updated_at=now() where id=(select order_id from public.print_invoices where id=s.invoice_id);
   elsif s.platform_code='host' then
    insert into public.host_payments(user_id,invoice_id,amount,currency,provider_reference,status,paid_at,transaction_ref,verified_at,provider_payload)
    values(s.user_id,s.invoice_id,s.amount,'NGN',receipt_ref,'verified',now(),receipt_ref,now(),jsonb_build_object('source','finance_verified_direct_transfer','submission_id',s.id,'bank_reference',s.customer_reference,'verified_by',auth.uid()));
   else
    insert into public.business_payments(invoice_id,user_id,amount,currency,provider_reference,status,paid_at)
    values(s.invoice_id,s.user_id,s.amount,'NGN',receipt_ref,'paid',now());
    update public.business_orders set amount=v_total,status='paid',updated_at=now() where id=(select order_id from public.business_invoices where id=s.invoice_id);
   end if;
   new_status='approved';
 else
   new_status='rejected';
 end if;

 update public.direct_transfer_submissions
 set status=new_status,admin_note=p_note,verified_by=auth.uid(),verified_at=now(),updated_at=now()
 where id=s.id and status in('awaiting_verification','pending');
 if not found then raise exception 'Submission has already been reviewed'; end if;

 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'direct_transfer_'||new_status,s.platform_code,'direct_transfer',s.id::text,jsonb_build_object('invoice_id',s.invoice_id,'amount',s.amount,'bank_reference',s.customer_reference,'finance_note',trim(p_note)));
 return jsonb_build_object('id',s.id,'status',new_status,'platform',s.platform_code,'invoice_id',s.invoice_id);
end
$function$;
revoke insert,update,delete on public.direct_transfer_submissions,public.ihlink_direct_transfer_submissions from authenticated,anon;
alter view public.ihlink_direct_transfer_submissions set (security_invoker=true);
revoke all on function public.review_direct_bank_transfer(uuid,text,text) from public,anon;
grant execute on function public.review_direct_bank_transfer(uuid,text,text) to authenticated;
revoke all on function public.submit_direct_bank_transfer(text,uuid,text,numeric,text,text,text,timestamptz,text) from public,anon;
grant execute on function public.submit_direct_bank_transfer(text,uuid,text,numeric,text,text,text,timestamptz,text) to authenticated;

-- Require explicit provider settlement and a verification timestamp before commercial activation.
CREATE OR REPLACE FUNCTION public.finalize_business_billstack_payment(p_intent uuid, p_transaction_ref text, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare intent public.business_payment_intents;inv public.business_invoices;ord public.business_orders;tx public.payment_transactions;begin
 if p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) or nullif(trim(p_transaction_ref),'') is null then raise exception 'Verified exact payment amount required'; end if;
 select * into intent from public.business_payment_intents where id=p_intent;if intent.id is null then raise exception 'Payment instruction not found';end if;
 select * into inv from public.business_invoices where id=intent.invoice_id for update;
 select * into intent from public.business_payment_intents where id=p_intent for update;
 select * into ord from public.business_orders where id=inv.order_id for update;
 select * into tx from public.payment_transactions where provider='billstack' and transaction_ref=p_transaction_ref for update;
 if intent.status='paid' then if intent.transaction_ref=p_transaction_ref and intent.amount=p_amount then return jsonb_build_object('status','already_paid','intent_id',intent.id);end if;raise exception 'Instruction already settled by a different transaction';end if;
 if intent.status<>'pending' or tx.id is null or tx.status not in ('verified','credited') or tx.is_settled is distinct from true or tx.verified_at is null or tx.credited_at is not null or tx.amount<>p_amount or tx.currency<>'NGN'
 or tx.user_id is distinct from intent.user_id or tx.platform_code is distinct from intent.unit_code or tx.virtual_account_id is distinct from intent.virtual_account_id then raise exception 'Verified transaction ownership, platform or replay validation failed';end if;
 if ord.id is distinct from intent.order_id or ord.user_id is distinct from intent.user_id or ord.unit_code is distinct from intent.unit_code or inv.status not in ('issued','awaiting_payment') or inv.currency<>'NGN'
 or p_amount<>intent.amount or p_amount<>(inv.amount-inv.amount_paid) then raise exception 'Invoice linkage or exact amount validation failed';end if;
 insert into public.business_payments(invoice_id,user_id,amount,currency,provider_reference,status,paid_at) values(inv.id,intent.user_id,p_amount,'NGN',p_transaction_ref,'paid',now());
 update public.business_invoices set amount_paid=amount_paid+p_amount,status='paid',updated_at=now() where id=inv.id;
 update public.business_orders set amount=inv.amount,status='paid',updated_at=now() where id=ord.id;
 update public.business_payment_intents set status='paid',transaction_ref=p_transaction_ref,paid_at=now(),updated_at=now() where id=intent.id;
 update public.payment_transactions set status='credited',credited_at=now(),updated_at=now() where id=tx.id;
 insert into public.business_notifications(user_id,unit_code,title,body) values(intent.user_id,intent.unit_code,'Payment verified','Invoice '||inv.invoice_number||' is paid. Your request is ready for authorized fulfilment.');
 return jsonb_build_object('status','paid','intent_id',intent.id,'invoice_id',inv.id);end $function$
;
CREATE OR REPLACE FUNCTION public.finalize_consult_billstack_payment(p_intent uuid, p_transaction_ref text, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i public.consult_payment_intents; inv public.consult_invoices; tx public.payment_transactions;
begin
 if p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) or nullif(btrim(p_transaction_ref),'') is null then raise exception 'Verified exact payment required'; end if;
 select * into i from public.consult_payment_intents where id=p_intent for update;
 if i.id is null then raise exception 'Payment intent unavailable'; end if;
 if i.status='paid' then
  if i.transaction_ref=p_transaction_ref and i.amount=p_amount then return jsonb_build_object('status','already_paid','intent_id',i.id); end if;
  raise exception 'Intent already settled by another transaction';
 end if;
 select * into tx from public.payment_transactions where provider='billstack' and transaction_ref=p_transaction_ref for update;
 if i.status<>'pending' or tx.id is null or tx.status not in('verified','credited') or tx.is_settled is distinct from true or tx.verified_at is null or tx.credited_at is not null or tx.amount<>p_amount or tx.currency<>'NGN'
  or tx.user_id is distinct from i.user_id or tx.platform_code is distinct from 'consult' or tx.virtual_account_id is distinct from i.virtual_account_id then
  raise exception 'Verified transaction ownership, platform or replay validation failed';
 end if;
 select * into inv from public.consult_invoices where id=i.invoice_id for update;
 if inv.id is null or inv.status not in('issued','part_paid','overdue') or inv.project_id<>i.project_id or inv.currency<>'NGN'
  or not exists(select 1 from public.consult_projects p where p.id=i.project_id and p.user_id=i.user_id)
  or p_amount<>i.amount or p_amount<>inv.amount-coalesce(inv.amount_paid,0) then raise exception 'Invoice linkage or exact amount validation failed'; end if;
 if exists(select 1 from public.consult_payments where payment_reference=p_transaction_ref) then raise exception 'Duplicate transaction'; end if;
 insert into public.consult_payments(project_id,payment_reference,amount,description,status,paid_at)
 values(i.project_id,p_transaction_ref,p_amount,'BillStack payment for '||inv.invoice_number,'paid',now());
 update public.consult_invoices set amount_paid=amount,status='paid',paid_at=now(),payment_reference=p_transaction_ref,updated_at=now() where id=inv.id;
 update public.consult_payment_intents set status='paid',transaction_ref=p_transaction_ref,paid_at=now(),updated_at=now() where id=i.id;
 update public.payment_transactions set status='credited',credited_at=now(),updated_at=now() where id=tx.id;
 update public.consult_projects set status=case when status in('pending','planning','quoted') then 'active' else status end,
  stage=case when stage in('proposal','quotation','planning') then 'delivery' else stage end,
  outstanding_amount=(select coalesce(sum(greatest(amount-coalesce(amount_paid,0),0)),0) from public.consult_invoices where project_id=i.project_id and status<>'cancelled'),
  updated_at=now() where id=i.project_id;
 insert into public.consult_activity_logs(project_id,actor_user_id,action,details)
 values(i.project_id,i.user_id,'invoice_settled',jsonb_build_object('invoice_id',inv.id,'intent_id',i.id,'transaction_ref',p_transaction_ref,'amount',p_amount,'source','verified_billstack'));
 return jsonb_build_object('status','paid','invoice_id',inv.id,'project_id',i.project_id);
end $function$
;
