CREATE OR REPLACE FUNCTION public.finalize_host_billstack_payment(p_intent uuid, p_transaction_ref text, p_amount numeric, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i public.host_payment_intents;o public.host_orders;tx public.payment_transactions;pid uuid;act text;provisioning_provider text;
begin
 if p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) or nullif(btrim(p_transaction_ref),'') is null then raise exception 'Verified exact payment required';end if;
 select * into i from public.host_payment_intents where id=p_intent for update;if i.id is null then raise exception 'Host payment intent not found';end if;
 if i.status='paid' then if i.transaction_ref=p_transaction_ref and i.amount=p_amount then return jsonb_build_object('status','already_paid','order_id',i.order_id);end if;raise exception 'Intent already settled by another transaction';end if;
 select * into tx from public.payment_transactions where provider='billstack' and transaction_ref=p_transaction_ref for update;
 if i.status<>'pending' or i.amount is distinct from p_amount or tx.id is null or tx.status not in('verified','credited') or tx.is_settled is distinct from true or tx.verified_at is null or tx.credited_at is not null or tx.amount<>p_amount or tx.currency<>'NGN' or tx.user_id is distinct from i.user_id or tx.platform_code is distinct from 'host' or tx.virtual_account_id is distinct from i.virtual_account_id then raise exception 'Verified transaction ownership, platform or replay validation failed';end if;
 select * into o from public.host_orders where id=i.order_id for update;
 if o.id is null or o.user_id<>i.user_id or o.amount<>p_amount or o.status<>'awaiting_payment' or o.payment_status='paid' or not exists(select 1 from public.host_invoices v where v.id=i.invoice_id and v.order_id=i.order_id and v.user_id=i.user_id and v.amount=p_amount and v.currency='NGN' and v.status in ('unpaid','issued','awaiting_payment','overdue')) then raise exception 'Host invoice/order linkage mismatch';end if;
 if exists(select 1 from public.host_payments where transaction_ref=p_transaction_ref) then raise exception 'Payment reference already processed';end if;
 insert into public.host_payments(user_id,invoice_id,amount,currency,provider_reference,status,paid_at,virtual_account_id,transaction_ref,verified_at,provider_payload) values(i.user_id,i.invoice_id,p_amount,'NGN',p_transaction_ref,'verified',now(),i.virtual_account_id,p_transaction_ref,now(),p_payload) returning id into pid;
 update public.host_invoices set status='paid',paid_at=now(),payment_reference=p_transaction_ref,payment_id=pid,updated_at=now() where id=i.invoice_id;
 update public.host_orders set payment_status='paid',status='paid',provisioning_status='pending',paid_at=now(),updated_at=now() where id=i.order_id;
 update public.host_payment_intents set status='paid',transaction_ref=p_transaction_ref,paid_at=now(),updated_at=now() where id=i.id;
 update public.payment_transactions set status='credited',credited_at=now(),updated_at=now() where id=tx.id;
 act:=case when o.renewal_service_id is not null then 'renew' when o.order_type='domain_registration' then 'domain_register' else 'hosting_provision' end;
 provisioning_provider:=case when o.order_type='domain_registration' and o.domain_name like '%.ng' then 'nira' when o.order_type='domain_registration' then 'international_registrar' else 'cpanel_whm' end;
 insert into public.host_provisioning_jobs(order_id,user_id,action,provider_code,status) values(o.id,o.user_id,act,provisioning_provider,'queued') on conflict(order_id,action) do update set status=case when public.host_provisioning_jobs.status='completed' then 'completed' else 'queued' end,updated_at=now();
 return jsonb_build_object('status','paid','invoice_id',i.invoice_id,'order_id',i.order_id,'provisioning_status','queued');
end$function$
;
CREATE OR REPLACE FUNCTION public.finalize_print_billstack_payment(p_intent uuid, p_transaction_ref text, p_amount numeric)
