 insert into public.print_payments(invoice_id,user_id,payment_intent_id,amount,currency,transaction_ref,provider_reference,status,paid_at)
 values(inv.id,i.user_id,i.id,p_amount,'NGN',p_transaction_ref,p_transaction_ref,'paid',now());
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(null,'print_verified_settlement','print','print_invoice',inv.id::text,jsonb_build_object('payment_intent_id',i.id,'transaction_ref',p_transaction_ref,'amount',p_amount));
