CREATE OR REPLACE FUNCTION public.finalize_schoolpro_subscription(p_intent uuid, p_transaction_ref text, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i public.schoolpro_subscription_intents%rowtype;c public.schoolpro_subscription_catalog%rowtype;tx public.payment_transactions%rowtype;existing public.schoolpro_subscriptions%rowtype;r timestamptz;
begin
 if p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) or nullif(btrim(p_transaction_ref),'') is null then raise exception 'Verified exact subscription payment required';end if;
 select * into i from public.schoolpro_subscription_intents where id=p_intent for update;if i.id is null then raise exception 'Subscription payment intent unavailable';end if;
 if i.billing_cycle<>'annual' then raise exception 'SchoolPro subscriptions are billed annually';end if;
 if i.status='paid' then if i.transaction_ref=p_transaction_ref and i.amount=p_amount then return jsonb_build_object('status','already_paid','school_id',i.school_id);end if;raise exception 'Subscription intent already settled by another transaction';end if;
 select * into tx from public.payment_transactions where provider='billstack' and transaction_ref=p_transaction_ref for update;
 if i.status<>'pending' or i.amount<>p_amount or tx.id is null or tx.status not in('verified','credited') or tx.is_settled is distinct from true or tx.verified_at is null or tx.credited_at is not null or tx.amount<>p_amount or tx.currency<>'NGN' or tx.user_id is distinct from i.payer_user_id or tx.platform_code is distinct from 'schoolpro' or tx.virtual_account_id is distinct from i.virtual_account_id then raise exception 'Verified transaction ownership, platform or replay validation failed';end if;
 select * into c from public.schoolpro_subscription_catalog where id=i.catalog_id and active=true;if c.id is null then raise exception 'Subscription plan is unavailable';end if;
 select * into existing from public.schoolpro_subscriptions where school_id=i.school_id for update;
 r:=case when existing.id is not null and existing.status='active' and existing.renews_at is not null and existing.renews_at>now() then existing.renews_at+interval '1 year' else now()+interval '1 year' end;
 insert into public.schoolpro_subscriptions(school_id,tier,billing_cycle,amount,status,starts_at,renews_at,managed_by_ihlink,updated_at)
 values(i.school_id,c.code,'annual',i.amount,'active',now(),r,true,now())
 on conflict(school_id) do update set tier=excluded.tier,billing_cycle='annual',amount=excluded.amount,status='active',starts_at=coalesce(public.schoolpro_subscriptions.starts_at,now()),renews_at=r,managed_by_ihlink=true,updated_at=now();
 update public.schoolpro_schools set status='active',plan=c.code,updated_at=now() where id=i.school_id;
 update public.schoolpro_subscription_intents set status='paid',transaction_ref=p_transaction_ref,paid_at=now(),updated_at=now() where id=i.id;
 update public.payment_transactions set status='credited',credited_at=now(),updated_at=now() where id=tx.id;
