 update public.schoolpro_schools set status='active',plan=c.code,updated_at=now() where id=i.school_id;
 update public.schoolpro_subscription_intents set status='paid',transaction_ref=p_transaction_ref,paid_at=now(),updated_at=now() where id=i.id;
 update public.payment_transactions set status='credited',credited_at=now(),updated_at=now() where id=tx.id;
