-- Automatic school fee invoices, using the existing fee and exception records.
create or replace function private.sync_schoolpro_fee_invoices(p_structure uuid,p_class text default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare f public.schoolpro_fee_structures; s public.schoolpro_students; ex public.schoolpro_fee_exceptions;
 old public.schoolpro_invoices; gross numeric; discount_amt numeric; scholarship_amt numeric; waiver_amt numeric; net numeric;
 issued integer:=0; refreshed integer:=0; retained integer:=0;
begin
 select * into f from public.schoolpro_fee_structures where id=p_structure for update;
 if f.id is null then raise exception 'Fee structure not found'; end if;
 if not f.is_active then return jsonb_build_object('processed',0,'issued',0,'updated',0,'retained',0); end if;
 select coalesce(sum(amount) filter(where not is_optional),0) into gross from public.schoolpro_fee_items where fee_structure_id=f.id;
 if gross=0 then gross:=f.amount; end if;
 if gross is null or gross<0 or gross<>round(gross,2) then raise exception 'Fee must be nonnegative with at most two decimal places'; end if;
 for s in select * from public.schoolpro_students where school_id=f.school_id and status='active'
 and (coalesce(p_class,f.class_name) is null or class_name=coalesce(p_class,f.class_name)) order by id loop
  ex:=null; select * into ex from public.schoolpro_fee_exceptions where school_id=f.school_id and student_id=s.id and term=f.term and session=f.session;
  discount_amt:=0;scholarship_amt:=0;waiver_amt:=0;
  if ex.id is not null then
   if ex.exception_type='full_waiver' or ex.waived then waiver_amt:=gross;
   elsif ex.exception_type='partial_waiver' then waiver_amt:=case when ex.value_type='percentage' then gross*ex.value/100 else coalesce(nullif(ex.value,0),ex.partial_waiver) end;
   elsif ex.exception_type='scholarship' then scholarship_amt:=case when ex.value_type='percentage' then gross*ex.value/100 else coalesce(nullif(ex.value,0),ex.scholarship) end;
   else discount_amt:=case when ex.value_type='percentage' then gross*ex.value/100 else coalesce(nullif(ex.value,0),ex.discount) end; end if;
  end if;
  discount_amt:=round(least(gross,greatest(0,discount_amt)),2);
  scholarship_amt:=round(least(gross-discount_amt,greatest(0,scholarship_amt)),2);
  waiver_amt:=round(least(gross-discount_amt-scholarship_amt,greatest(0,waiver_amt)),2);
  net:=greatest(0,gross-discount_amt-scholarship_amt-waiver_amt);
  select * into old from public.schoolpro_invoices where student_id=s.id and fee_structure_id=f.id for update;
  if old.id is null then
   insert into public.schoolpro_invoices(school_id,student_id,fee_structure_id,title,term,session,gross_amount,amount_due,due_date,discount,scholarship,waiver_amount,status,notes,created_by)
   values(f.school_id,s.id,f.id,f.name,f.term,f.session,gross,net,f.due_date,discount_amt,scholarship_amt,waiver_amt,
   case when net=0 then 'waived'::public.schoolpro_invoice_status else 'unpaid'::public.schoolpro_invoice_status end,ex.notes,coalesce(auth.uid(),f.created_by));
   issued:=issued+1;
  elsif old.amount_paid>0 or old.status in ('paid','part_paid') then retained:=retained+1;
  elsif (old.amount_due,old.gross_amount,old.discount,old.scholarship,old.waiver_amount,old.title,old.due_date)
   is distinct from (net,gross,discount_amt,scholarship_amt,waiver_amt,f.name,f.due_date) then
   if exists(select 1 from public.schoolpro_payment_intents where invoice_id=old.id and status='pending') then
    raise exception 'A pending payment instruction must be reconciled before changing this fee';
   end if;
   update public.schoolpro_invoices set title=f.name,amount_due=net,gross_amount=gross,discount=discount_amt,
    scholarship=scholarship_amt,waiver_amount=waiver_amt,due_date=f.due_date,notes=ex.notes,
    status=case when net=0 then 'waived'::public.schoolpro_invoice_status else 'unpaid'::public.schoolpro_invoice_status end,updated_at=now() where id=old.id;
   refreshed:=refreshed+1;
  else retained:=retained+1; end if;
 end loop;
 if issued+refreshed>0 then
  insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
  values(auth.uid(),'School fee invoices synchronized','schoolpro','fee_structure',f.id::text,
    jsonb_build_object('school_id',f.school_id,'issued',issued,'updated',refreshed,'retained',retained));
 end if;
 return jsonb_build_object('processed',issued+refreshed+retained,'issued',issued,'updated',refreshed,'retained',retained,'gross',gross);
end $$;
revoke all on function private.sync_schoolpro_fee_invoices(uuid,text) from public,anon,authenticated;

create or replace function public.generate_schoolpro_class_invoices(p_structure uuid,p_class text default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare school uuid;
begin
 select school_id into school from public.schoolpro_fee_structures where id=p_structure;
 if auth.uid() is null or not coalesce(private.schoolpro_module_allowed(school,'finance'),false)
 or not coalesce(private.has_school_access(school,array['proprietor','administrator','accountant','bursar']::public.school_member_role[]),false)
 then raise exception 'School finance permission required'; end if;
 return private.sync_schoolpro_fee_invoices(p_structure,p_class);
end $$;
revoke all on function public.generate_schoolpro_class_invoices(uuid,text) from public,anon;
grant execute on function public.generate_schoolpro_class_invoices(uuid,text) to authenticated;

create or replace function private.schoolpro_auto_fee_invoices()
returns trigger language plpgsql security definer set search_path='' as $$
begin
 if TG_TABLE_NAME='schoolpro_fee_structures' then
  if TG_OP='UPDATE' and (new.school_id,new.term,new.session,new.class_name) is distinct from (old.school_id,old.term,old.session,old.class_name)
   and exists(select 1 from public.schoolpro_invoices where fee_structure_id=new.id) then
   raise exception 'Create a new fee schedule for a different school, class, term or session; existing invoices retain their identity';
  end if;
  perform private.sync_schoolpro_fee_invoices(new.id,null);
 elsif TG_TABLE_NAME='schoolpro_fee_items' then
  if TG_OP='DELETE' and not exists(select 1 from public.schoolpro_fee_structures where id=old.fee_structure_id) then return null; end if;
  if TG_OP='UPDATE' and new.fee_structure_id is distinct from old.fee_structure_id then
   perform private.sync_schoolpro_fee_invoices(old.fee_structure_id,null);
  end if;
  perform private.sync_schoolpro_fee_invoices(case when TG_OP='DELETE' then old.fee_structure_id else new.fee_structure_id end,null);
 end if;
 return null;
end $$;
revoke all on function private.schoolpro_auto_fee_invoices() from public,anon,authenticated;
create trigger schoolpro_fee_schedule_auto_invoice after insert or update on public.schoolpro_fee_structures
 for each row execute function private.schoolpro_auto_fee_invoices();
CREATE OR REPLACE FUNCTION public.record_schoolpro_payment(target_invoice uuid, payment_amount numeric, payment_method text, payment_reference text, payment_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  invoice_row public.schoolpro_invoices%rowtype;
  payment_id uuid;
  new_paid numeric;
begin
  select * into invoice_row from public.schoolpro_invoices where id=target_invoice for update;
  if invoice_row.id is null then raise exception 'Invoice not found'; end if;
  if not private.has_school_access(invoice_row.school_id,array['proprietor','administrator','accountant','bursar']::public.school_member_role[]) then raise exception 'Permission denied'; end if;
  if payment_amount is null or payment_amount<=0 or payment_amount<>round(payment_amount,2) then raise exception 'A positive payment with at most two decimal places is required'; end if;
  if nullif(trim(payment_reference),'') is null then raise exception 'Payment reference is required'; end if;
  if payment_amount <= 0 or invoice_row.amount_paid + payment_amount > invoice_row.amount_due then raise exception 'Payment exceeds the outstanding invoice balance'; end if;
  if payment_method not in ('cash','transfer','card','pos','cheque','other') then raise exception 'Unsupported payment method'; end if;
  insert into public.schoolpro_fee_payments(school_id,invoice_id,student_id,amount,method,reference,notes,recorded_by)
  values(invoice_row.school_id,invoice_row.id,invoice_row.student_id,payment_amount,payment_method,trim(payment_reference),payment_notes,(select auth.uid())) returning id into payment_id;
  new_paid := invoice_row.amount_paid + payment_amount;
  update public.schoolpro_invoices set amount_paid=new_paid,status=case when new_paid>=amount_due then 'paid'::public.schoolpro_invoice_status else 'part_paid'::public.schoolpro_invoice_status end,updated_at=now() where id=invoice_row.id;
  return payment_id;
end;
$function$;
create trigger schoolpro_fee_items_auto_invoice after insert or update or delete on public.schoolpro_fee_items
 for each row execute function private.schoolpro_auto_fee_invoices();

