create or replace function public.admin_request_customer_deletion(p_user uuid,p_reason text default null)
returns public.account_deletion_requests language plpgsql security definer set search_path='' as $$
declare actor public.profiles; subject public.profiles; request public.account_deletion_requests;
begin
 select * into actor from public.profiles where id=auth.uid();
 if actor.id is null or actor.role is distinct from 'super_admin'::public.user_role or actor.status is distinct from 'active'::public.account_status then raise exception 'Active Super Admin required'; end if;
 select * into subject from public.profiles where id=p_user for update;
 if subject.id is null or subject.role is distinct from 'customer'::public.user_role then raise exception 'Select a customer account; administrator identities use role management'; end if;
 select * into request from public.account_deletion_requests where user_id=p_user and status in ('pending','approved') order by requested_at desc limit 1;
 if request.id is not null then return request; end if;
 if exists(select 1 from public.account_deletion_requests where user_id=p_user and status='completed') then raise exception 'Customer account deletion is already complete'; end if;
 insert into public.account_deletion_requests(user_id,status,reason) values(p_user,'pending',coalesce(nullif(trim(p_reason),''),'Deletion initiated by Super Admin')) returning * into request;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(actor.id,'Super Admin initiated customer deletion review','corporate','account_deletion_request',request.id::text,jsonb_build_object('subject_user_id',p_user));
 return request;
end $$;
revoke all on function public.admin_request_customer_deletion(uuid,text) from public,anon;
grant execute on function public.admin_request_customer_deletion(uuid,text) to authenticated;

