returns jsonb language plpgsql security definer set search_path='' as $$
declare request public.account_deletion_requests; subject public.profiles;
begin
 if not exists(select 1 from public.profiles where id=p_actor and role='super_admin' and status='active') then raise exception 'Active Super Admin required'; end if;
 select * into request from public.account_deletion_requests where id=p_request for update;
 if request.id is null then raise exception 'Deletion request not found'; end if;
 if request.status='completed' then return jsonb_build_object('status','completed'); end if;
 if request.status is distinct from 'approved' then raise exception 'Approved request required'; end if;
 select * into subject from public.profiles where id=request.user_id for update;
 if subject.id is null or subject.role is distinct from 'customer'::public.user_role then raise exception 'Customer account required'; end if;
 update public.profiles set email='deleted+'||subject.id::text||'@anonymized.ihlink.invalid',first_name=null,middle_name=null,last_name=null,phone=null,sex=null,
 newsletter_opt_in=false,requested_service=null,status='suspended',updated_at=now() where id=subject.id;
 update public.customer_service_access set status='suspended' where user_id=subject.id;
 update public.account_deletion_requests set status='completed',completed_at=now(),resolved_at=now(),updated_at=now(),finalised_by=p_actor,anonymised=true,reason=null where id=request.id;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(p_actor,'Finalised account deletion with Auth soft-delete and profile anonymisation','corporate','account_deletion_request',request.id::text,
