-- Operational metadata only: financial history, identities and ownership are excluded.
create or replace function public.admin_edit_operational_record(p_table text,p_id uuid,p_changes jsonb,p_expected jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare allowed text[]; previous jsonb; result jsonb; assignments text; key text; value jsonb; product text;
begin
 if auth.uid() is null or not exists(select 1 from public.profiles where id=auth.uid() and role='super_admin' and status='active') then raise exception 'Active Super Admin required'; end if;
 allowed:=case p_table
 when 'business_catalog' then array['name','category','description','pricing_unit','is_active']
 when 'consult_service_catalog' then array['name','category','description','typical_timeline','is_active']
 when 'host_plans' then array['name','category','description','is_active']
 when 'print_products' then array['name','category','description','active']
 when 'academy_courses' then array['title','category','description','duration_text','delivery_mode','is_active']
 when 'schoolpro_announcements' then array['title','body','audience']
 when 'schoolpro_calendar_events' then array['title','event_date','event_type','details']
 when 'schoolpro_hostel_rooms' then array['hostel_name','room']
 when 'schoolpro_inventory_assets' then array['name','category','condition','location']
 when 'schoolpro_library_books' then array['title','author','isbn']
 when 'schoolpro_transport_routes' then array['name','vehicle','driver_name','driver_phone']
 else null end;
 if allowed is null then raise exception 'This record requires its dedicated management workflow'; end if;
 if jsonb_typeof(p_changes) is distinct from 'object' or p_changes='{}'::jsonb or jsonb_typeof(p_expected) is distinct from 'object' then raise exception 'Changed fields and expected values required'; end if;
 if exists(select 1 from jsonb_object_keys(p_changes) k where not(k=any(allowed))) then raise exception 'Unsupported field'; end if;
 for key,value in select * from jsonb_each(p_changes) loop
  if not(p_expected ? key) then raise exception 'Expected value required for %',key; end if;
  if key in('is_active','active') then
   if jsonb_typeof(value)<>'boolean' then raise exception 'Boolean value required for %',key; end if;
  elsif jsonb_typeof(value) not in('string','null') then raise exception 'Text value required for %',key;
  elsif length(coalesce(value#>>'{}',''))>10000 then raise exception 'Field too long';
  elsif key in('name','title','category','hostel_name','room') and nullif(trim(value#>>'{}'),'') is null then raise exception '% cannot be blank',key; end if;
 end loop;
 execute format('select to_jsonb(r) from public.%I r where id=$1 for update',p_table) into previous using p_id;
 if previous is null then raise exception 'Record not found'; end if;
 for key in select jsonb_object_keys(p_changes) loop
  if previous->key is distinct from p_expected->key then raise exception 'Record changed. Refresh before saving'; end if;
 end loop;
 select string_agg(format('%I=(jsonb_populate_record(null::public.%I,$1)).%I',k,p_table,k),',') into assignments from jsonb_object_keys(p_changes) k;
 if p_table in('business_catalog','consult_service_catalog','host_plans','print_products','academy_courses') then assignments:=assignments||',updated_at=now()'; end if;
 execute format('update public.%I r set %s where id=$2 returning to_jsonb(r)',p_table,assignments) into result using p_changes,p_id;
 product:=case when p_table like 'schoolpro_%' then 'schoolpro' when p_table='consult_service_catalog' then 'consult' when p_table='host_plans' then 'host' when p_table='print_products' then 'print' when p_table='academy_courses' then 'academy' else coalesce(previous->>'unit_code','business_centre') end;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'operational_record_edited',product,p_table,p_id::text,jsonb_build_object('fields',p_changes,'previous',p_expected));
 return result;
end $$;
revoke all on function public.admin_edit_operational_record(text,uuid,jsonb,jsonb) from public,anon;
grant execute on function public.admin_edit_operational_record(text,uuid,jsonb,jsonb) to authenticated;

