create or replace function public.admin_set_linked_service_price(p_id uuid,p_price numeric,p_expected numeric)
returns uuid language plpgsql security definer set search_path='' as $$
declare item public.service_catalog; changed uuid;
begin
 if auth.uid() is null or not exists(select 1 from public.profiles where id=auth.uid() and role='super_admin' and status='active') then raise exception 'Active Super Admin required'; end if;
 if p_price is not null and (p_price<0 or p_price<>round(p_price,2) or p_price::text in('NaN','Infinity','-Infinity')) then raise exception 'Non-negative exact price required'; end if;
 select * into item from public.service_catalog where id=p_id for update;
 if item.id is null then raise exception 'Service not found'; end if;
 if item.base_price is distinct from p_expected then raise exception 'Price changed. Refresh before saving'; end if;
 if item.source_table is not null then
  if item.source_id is null then raise exception 'Linked catalogue record missing'; end if;
  if item.source_table='business_catalog' then update public.business_catalog set base_price=p_price,updated_at=now() where id=item.source_id returning id into changed;
  elsif item.source_table='host_plans' and p_price is not null then update public.host_plans set monthly_price=p_price,updated_at=now() where id=item.source_id returning id into changed;
  elsif item.source_table='host_domain_prices' and p_price is not null then update public.host_domain_prices set registration_price=p_price,updated_at=now() where id=item.source_id returning id into changed;
  else raise exception 'Use the dedicated pricing workflow for this source'; end if;
  if changed is null then raise exception 'Linked catalogue record missing'; end if;
 end if;
 update public.service_catalog set base_price=p_price,updated_at=now() where id=item.id;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'linked_service_price_changed','system','service_catalog',item.id::text,jsonb_build_object('previous_price',item.base_price,'price',p_price,'source_table',item.source_table,'source_id',item.source_id));
 return item.id;
end $$;
revoke all on function public.admin_set_linked_service_price(uuid,numeric,numeric) from public,anon;
grant execute on function public.admin_set_linked_service_price(uuid,numeric,numeric) to authenticated;

