create or replace function public.prepare_schoolpro_bank_subscription(p_school uuid,p_catalog uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare s public.schoolpro_schools%rowtype;c public.schoolpro_subscription_catalog%rowtype;i public.schoolpro_subscription_intents%rowtype;
begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) then raise exception 'Active account required';end if;
 select * into s from public.schoolpro_schools where id=p_school for update;
 if s.id is null or s.status='suspended' then raise exception 'School unavailable';end if;
 if s.owner_id is distinct from auth.uid() and not exists(select 1 from public.schoolpro_members where school_id=s.id and user_id=auth.uid() and role in('proprietor','administrator','bursar')) then raise exception 'School billing permission required';end if;
 select * into c from public.schoolpro_subscription_catalog where id=p_catalog and active=true;
 if c.id is null or c.annual_price is null or c.annual_price<=0 or c.annual_price<>round(c.annual_price,2) then raise exception 'Published annual plan price required';end if;
 if not exists(select 1 from public.ihlink_bank_accounts where is_active) then raise exception 'Company bank accounts unavailable';end if;
 select * into i from public.schoolpro_subscription_intents where school_id=s.id and status='pending' order by created_at limit 1 for update;
 if i.id is not null then
  if i.payment_method<>'bank_transfer' or i.payer_user_id is distinct from auth.uid() or i.catalog_id is distinct from c.id or i.amount is distinct from c.annual_price then raise exception 'Existing subscription instruction requires Finance review before changing plan or payer';end if;
  return to_jsonb(i);
 end if;
 insert into public.schoolpro_subscription_intents(school_id,payer_user_id,catalog_id,billing_cycle,amount,virtual_account_id,reference,status,payment_method) values(s.id,auth.uid(),c.id,'annual',c.annual_price,null,'SCHSUB-'||upper(replace(gen_random_uuid()::text,'-','')),'pending','bank_transfer') returning * into i;
 return to_jsonb(i);
end $$;
revoke all on function public.prepare_schoolpro_bank_subscription(uuid,uuid) from public,anon;
grant execute on function public.prepare_schoolpro_bank_subscription(uuid,uuid) to authenticated;

create or replace function public.submit_service_bank_transfer(p_platform text,p_invoice uuid,p_bank_account uuid,p_source_reference text,p_amount numeric,p_sender_name text,p_sender_bank text,p_customer_reference text,p_transferred_at timestamptz,p_proof_storage_path text) returns uuid language plpgsql security definer set search_path='' as $$
declare v_id uuid;i public.schoolpro_subscription_intents%rowtype;
begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) then raise exception 'Active account required';end if;
 if p_transferred_at>now() then raise exception 'Transfer date cannot be in the future';end if;
 perform 1 from public.ihlink_bank_accounts where id=p_bank_account and is_active for update;
 if not found then raise exception 'Choose an active company receiving account';end if;
 if p_platform='schoolpro_subscription' then
  select * into i from public.schoolpro_subscription_intents where id=p_invoice for update;
  if i.id is null or i.payer_user_id is distinct from auth.uid() or i.status<>'pending' or i.payment_method<>'bank_transfer' then raise exception 'Owned pending bank subscription instruction required';end if;
  if p_amount is distinct from i.amount or p_amount<=0 then raise exception 'Transfer must match the subscription amount';end if;
  if length(trim(coalesce(p_sender_name,'')))=0 or length(trim(coalesce(p_customer_reference,'')))=0 then raise exception 'Sender and bank reference required';end if;
  if p_proof_storage_path not like auth.uid()::text||'/%' or not exists(select 1 from storage.objects where bucket_id='direct-transfer-proofs' and name=p_proof_storage_path) then raise exception 'Saved customer-owned receipt required';end if;
  if exists(select 1 from public.direct_transfer_submissions where platform_code=p_platform and invoice_id=i.id and status in('awaiting_verification','pending','approved','verified')) then raise exception 'This subscription already has a proof awaiting review or settled';end if;
  insert into public.direct_transfer_submissions(user_id,platform_code,invoice_id,source_reference,bank_account_id,amount,sender_name,sender_bank,customer_reference,transferred_at,proof_storage_path,status) values(auth.uid(),p_platform,i.id,i.reference,p_bank_account,i.amount,trim(p_sender_name),nullif(trim(p_sender_bank),''),trim(p_customer_reference),p_transferred_at,p_proof_storage_path,'awaiting_verification') returning id into v_id;
 else
  v_id:=public.submit_direct_bank_transfer(p_platform,p_invoice,p_source_reference,p_amount,p_sender_name,p_sender_bank,p_customer_reference,p_transferred_at,p_proof_storage_path);
  update public.direct_transfer_submissions set bank_account_id=p_bank_account where id=v_id and user_id=auth.uid();
 end if;
 return v_id;
end $$;
revoke all on function public.submit_service_bank_transfer(text,uuid,uuid,text,numeric,text,text,text,timestamptz,text) from public,anon;
grant execute on function public.submit_service_bank_transfer(text,uuid,uuid,text,numeric,text,text,text,timestamptz,text) to authenticated;

create or replace function private.review_school_subscription_transfer(p_submission uuid,p_decision text,p_note text) returns jsonb language plpgsql security definer set search_path='' as $$
declare t public.direct_transfer_submissions%rowtype;i public.schoolpro_subscription_intents%rowtype;c public.schoolpro_subscription_catalog%rowtype;s public.schoolpro_subscriptions%rowtype;r timestamptz;receipt text;
begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) or not coalesce(private.is_admin(array['super_admin','finance']::public.user_role[]),false) then raise exception 'Company Finance approval permission required';end if;
 if p_decision is null or p_decision not in('approved','rejected') or length(trim(coalesce(p_note,'')))<3 then raise exception 'Review decision and verification note required';end if;
 select * into t from public.direct_transfer_submissions where id=p_submission and platform_code='schoolpro_subscription' for update;
 if t.id is null then raise exception 'Subscription proof unavailable';end if;
 if t.status=p_decision then return jsonb_build_object('id',t.id,'status',t.status);end if;
 if t.status not in('pending','awaiting_verification') then raise exception 'Proof already reviewed';end if;
 select * into i from public.schoolpro_subscription_intents where id=t.invoice_id for update;
 if i.id is null or i.status<>'pending' or i.payment_method<>'bank_transfer' or i.payer_user_id is distinct from t.user_id or i.amount is distinct from t.amount or i.billing_cycle<>'annual' then raise exception 'Subscription proof does not match the pending instruction';end if;
 if p_decision='approved' then
  if t.proof_storage_path not like t.user_id::text||'/%' or not exists(select 1 from storage.objects where bucket_id='direct-transfer-proofs' and name=t.proof_storage_path) then raise exception 'Saved customer receipt required';end if;
  perform 1 from public.ihlink_bank_accounts where id=t.bank_account_id for update;
  if not found then raise exception 'Receiving account unavailable';end if;
  if exists(select 1 from public.direct_transfer_submissions where id<>t.id and status in('approved','verified') and bank_account_id=t.bank_account_id and lower(trim(customer_reference))=lower(trim(t.customer_reference))) then raise exception 'Bank reference already reconciled';end if;
  perform 1 from public.schoolpro_schools where id=i.school_id and status<>'suspended' for update;
  if not found then raise exception 'School requires review before activation';end if;
  select * into c from public.schoolpro_subscription_catalog where id=i.catalog_id and active;
  if c.id is null then raise exception 'Subscription plan unavailable';end if;
  select * into s from public.schoolpro_subscriptions where school_id=i.school_id for update;
  r:=case when s.status='active' and s.renews_at>now() then s.renews_at+interval '1 year' else now()+interval '1 year' end;
  insert into public.schoolpro_subscriptions(school_id,tier,billing_cycle,amount,status,starts_at,renews_at,managed_by_ihlink,updated_at) values(i.school_id,c.code,'annual',i.amount,'active',now(),r,true,now()) on conflict(school_id) do update set tier=excluded.tier,billing_cycle='annual',amount=excluded.amount,status='active',starts_at=coalesce(public.schoolpro_subscriptions.starts_at,now()),renews_at=r,managed_by_ihlink=true,updated_at=now() returning * into s;
  update public.schoolpro_schools set status='active',plan=c.code,updated_at=now() where id=i.school_id;
  receipt:='DIRECT-'||t.id::text;
  update public.schoolpro_subscription_intents set status='paid',transaction_ref=receipt,paid_at=now(),updated_at=now() where id=i.id;
  insert into public.schoolpro_subscription_payments(school_id,subscription_id,payer_user_id,provider,reference,amount,status,transaction_ref,provider_payload,verified_at,credited_at) values(i.school_id,s.id,i.payer_user_id,'bank_transfer',receipt,i.amount,'credited',receipt,jsonb_build_object('submission_id',t.id,'bank_account_id',t.bank_account_id,'bank_reference',t.customer_reference,'verified_by',auth.uid()),now(),now());
 end if;
 update public.direct_transfer_submissions set status=p_decision,admin_note=trim(p_note),verified_by=auth.uid(),verified_at=now(),updated_at=now() where id=t.id;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'subscription_transfer_'||p_decision,'schoolpro','direct_transfer',t.id::text,jsonb_build_object('school_id',i.school_id,'intent_id',i.id,'amount',t.amount,'bank_reference',t.customer_reference,'finance_note',trim(p_note)));
 return jsonb_build_object('id',t.id,'status',p_decision,'school_id',i.school_id);
end $$;
revoke all on function private.review_school_subscription_transfer(uuid,text,text) from public,anon,authenticated;

-- Disable obsolete database gateway APIs, retaining their history and signatures.
do $disable$ declare f record;begin
 for f in select p.oid,p.proname from pg_proc p where p.pronamespace='public'::regnamespace and (p.proname like 'finalize_%_billstack_payment' or p.proname in('prepare_service_invoice_payment','prepare_schoolpro_subscription_payment','finalize_schoolpro_subscription','finalize_schoolpro_payment','create_business_payment_intent')) loop
  execute replace(pg_get_functiondef(f.oid),substring(pg_get_functiondef(f.oid) from '(?s)AS \$function\$(.*)\$function\$'),'begin raise exception ''This service accepts bank transfer and Finance-reviewed payment proof only'';end ');
 end loop;
end $disable$;

alter policy "school managers read subscription intents" on public.schoolpro_subscription_intents using ((payer_user_id=auth.uid()) or private.has_school_access(school_id,array['proprietor','administrator','bursar']::public.school_member_role[]) or private.is_admin(array['super_admin','finance']::public.user_role[]));

CREATE OR REPLACE FUNCTION public.review_direct_bank_transfer(p_submission uuid, p_decision text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 s public.direct_transfer_submissions%rowtype; new_status text;
 v_owner uuid; v_total numeric; v_paid numeric:=0; v_unit text; v_balance numeric; v_rows int; invoice_table text; invoice_state text; invoice_currency text; receipt_ref text;
begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) then raise exception 'Authentication required'; end if;
 if p_decision is null or p_decision not in('approved','rejected') then raise exception 'Decision must be approved or rejected'; end if;

 select * into s from public.direct_transfer_submissions where id=p_submission for update;
 if s.id is null then raise exception 'Submission not found'; end if;
 if s.platform_code='schoolpro_subscription' then return private.review_school_subscription_transfer(p_submission,p_decision,p_note);end if;
 if not coalesce((private.is_admin(array['super_admin'::public.user_role,'finance'::public.user_role]) or private.business_staff_allowed(s.platform_code,'approve')),false)
   then raise exception 'Platform finance approval permission required'; end if;
 if length(trim(coalesce(p_note,'')))<3 then raise exception 'Finance verification or rejection note must contain at least 3 characters'; end if;
 if s.status=p_decision then return jsonb_build_object('id',s.id,'status',s.status,'platform',s.platform_code,'invoice_id',s.invoice_id); end if;
 if s.status not in('awaiting_verification','pending') then raise exception 'Submission has already been reviewed'; end if;

 if p_decision='approved' then
   if s.proof_storage_path is null or s.proof_storage_path not like s.user_id::text||'/%' or not exists(select 1 from storage.objects where bucket_id='direct-transfer-proofs' and name=s.proof_storage_path) then raise exception 'A saved customer-owned transfer proof is required'; end if;
   perform 1 from public.ihlink_bank_accounts where id=s.bank_account_id for update;
   if not found then raise exception 'Receiving bank account not found'; end if;
   if exists(select 1 from public.direct_transfer_submissions d where d.id<>s.id and d.status in('approved','verified') and d.bank_account_id=s.bank_account_id and lower(trim(d.customer_reference))=lower(trim(s.customer_reference))) then raise exception 'This bank transfer reference has already been reconciled'; end if;
   invoice_table:=case s.platform_code when 'consult' then 'consult_invoices' when 'engineering' then 'engineering_invoices' when 'print' then 'print_invoices' when 'host' then 'host_invoices' when 'fabrication' then 'business_invoices' when 'compute' then 'business_invoices' when 'academy' then 'business_invoices' when 'digital_business' then 'business_invoices' when 'business_centre' then 'business_invoices' end;
   if invoice_table is null then raise exception 'Unsupported direct-transfer platform'; end if;
   execute format('select status,currency from public.%I where id=$1 for update',invoice_table) into invoice_state,invoice_currency using s.invoice_id;
   if invoice_state is null or invoice_state not in ('issued','unpaid','part_paid','overdue','awaiting_payment') or invoice_currency<>'NGN' then raise exception 'Payable NGN invoice required'; end if;
   receipt_ref:='DIRECT-'||s.id::text;
   if s.platform_code='consult' then
     select pr.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid
     from public.consult_invoices i join public.consult_projects pr on pr.id=i.project_id where i.id=s.invoice_id for update of i;
   elsif s.platform_code='engineering' then
     select pr.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid
     from public.engineering_invoices i join public.engineering_projects pr on pr.id=i.project_id where i.id=s.invoice_id for update of i;
   elsif s.platform_code='print' then
     select o.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid
     from public.print_invoices i join public.print_orders o on o.id=i.order_id where i.id=s.invoice_id for update of i;
   elsif s.platform_code='host' then
     select i.user_id,i.amount,case when i.status='paid' then i.amount else 0 end into v_owner,v_total,v_paid
     from public.host_invoices i where i.id=s.invoice_id for update;
   elsif s.platform_code in('fabrication','compute','academy','digital_business','business_centre') then
     select o.user_id,i.amount,coalesce(i.amount_paid,0),o.unit_code into v_owner,v_total,v_paid,v_unit
     from public.business_invoices i join public.business_orders o on o.id=i.order_id where i.id=s.invoice_id for update of i;
     if v_owner is not null and v_unit<>s.platform_code then raise exception 'Submission platform does not match invoice platform'; end if;
   else
     raise exception 'Unsupported direct-transfer platform';
   end if;

   if v_owner is null or v_owner<>s.user_id then raise exception 'Transfer submission does not match invoice owner'; end if;
   v_balance:=greatest(coalesce(v_total,0)-coalesce(v_paid,0),0);
   if s.amount is null or s.amount<=0 or s.amount<>round(s.amount,2) then raise exception 'Positive exact transfer amount required'; end if;
   if v_balance<=0 then raise exception 'Invoice has already been settled'; end if;
   if s.amount<>v_balance then raise exception 'Transfer amount no longer matches the outstanding invoice balance'; end if;

   if s.platform_code='consult' then
     update public.consult_invoices set amount_paid=amount,status='paid',paid_at=now(),payment_reference=s.customer_reference,updated_at=now()
     where id=s.invoice_id;
   elsif s.platform_code='engineering' then
     update public.engineering_invoices set amount_paid=amount,status='paid',updated_at=now() where id=s.invoice_id;
   elsif s.platform_code='print' then
     update public.print_invoices set amount_paid=amount,status='paid',updated_at=now() where id=s.invoice_id;
   elsif s.platform_code='host' then
     update public.host_invoices set status='paid',paid_at=now(),payment_reference=s.customer_reference,updated_at=now() where id=s.invoice_id;
     update public.host_orders set payment_status='paid',paid_at=now(),status=case when status='awaiting_payment' then 'paid' else status end,updated_at=now()
     where id=(select order_id from public.host_invoices where id=s.invoice_id);
   else
     update public.business_invoices set amount_paid=amount,status='paid',updated_at=now() where id=s.invoice_id;
   end if;
   get diagnostics v_rows = row_count;
   if v_rows=0 then raise exception 'Invoice settlement failed'; end if;

   if s.platform_code='consult' then
    insert into public.consult_payments(project_id,payment_reference,amount,description,status,paid_at)
    select project_id,receipt_ref,s.amount,'Finance-verified direct bank transfer','paid',now() from public.consult_invoices where id=s.invoice_id;
    update public.consult_projects set outstanding_amount=(select coalesce(sum(greatest(amount-amount_paid,0)),0) from public.consult_invoices where project_id=public.consult_projects.id and status<>'cancelled'),updated_at=now() where id=(select project_id from public.consult_invoices where id=s.invoice_id);
   elsif s.platform_code='engineering' then
    insert into public.engineering_payments(invoice_id,user_id,amount,currency,transaction_ref,provider_reference,provider,status,paid_at)
    values(s.invoice_id,s.user_id,s.amount,'NGN',receipt_ref,receipt_ref,'direct_transfer','paid',now());
   elsif s.platform_code='print' then
    insert into public.print_payments(invoice_id,user_id,amount,currency,transaction_ref,provider_reference,provider,status,paid_at)
    values(s.invoice_id,s.user_id,s.amount,'NGN',receipt_ref,receipt_ref,'direct_transfer','paid',now());
    update public.print_orders set status=case when status in ('request','quoted','awaiting_payment') then 'artwork' else status end,updated_at=now() where id=(select order_id from public.print_invoices where id=s.invoice_id);
   elsif s.platform_code='host' then
    insert into public.host_payments(user_id,invoice_id,amount,currency,provider_reference,status,paid_at,transaction_ref,verified_at,provider_payload)
    values(s.user_id,s.invoice_id,s.amount,'NGN',receipt_ref,'verified',now(),receipt_ref,now(),jsonb_build_object('source','finance_verified_direct_transfer','submission_id',s.id,'bank_reference',s.customer_reference,'verified_by',auth.uid()));
   else
    insert into public.business_payments(invoice_id,user_id,amount,currency,provider_reference,status,paid_at)
    values(s.invoice_id,s.user_id,s.amount,'NGN',receipt_ref,'paid',now());
    update public.business_orders set amount=v_total,status='paid',updated_at=now() where id=(select order_id from public.business_invoices where id=s.invoice_id);
   end if;
   new_status='approved';
 else
   new_status='rejected';
 end if;

 update public.direct_transfer_submissions
 set status=new_status,admin_note=p_note,verified_by=auth.uid(),verified_at=now(),updated_at=now()
 where id=s.id and status in('awaiting_verification','pending');
 if not found then raise exception 'Submission has already been reviewed'; end if;

 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'direct_transfer_'||new_status,s.platform_code,'direct_transfer',s.id::text,jsonb_build_object('invoice_id',s.invoice_id,'amount',s.amount,'bank_reference',s.customer_reference,'finance_note',trim(p_note)));
 return jsonb_build_object('id',s.id,'status',new_status,'platform',s.platform_code,'invoice_id',s.invoice_id);
end
$function$;


CREATE OR REPLACE FUNCTION public.credit_verified_payment(p_user uuid, p_provider text, p_platform text, p_transaction_ref text, p_amount numeric, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare tx public.payment_transactions%rowtype; fs public.payment_fee_settings%rowtype; before_balance numeric; after_balance numeric; ledger_id uuid; fee numeric:=0; net numeric; expected_platform text;
begin
 if lower(coalesce(p_provider,''))='billstack' and lower(coalesce(p_platform,''))<>'datasub' then raise exception 'BillStack is restricted to DataSub';end if;
 if p_user is null or p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2)
    or nullif(btrim(p_provider),'') is null or nullif(btrim(p_transaction_ref),'') is null then raise exception 'Invalid verified credit'; end if;
 expected_platform:=lower(coalesce(nullif(btrim(p_platform),''),'corporate'));
 select * into tx from public.payment_transactions
 where lower(provider)=lower(btrim(p_provider)) and transaction_ref=btrim(p_transaction_ref) for update;
 if tx.id is null then raise exception 'Verified payment transaction not found'; end if;
 if tx.user_id is distinct from p_user then raise exception 'Payment owner mismatch'; end if;
 if tx.amount<>p_amount then raise exception 'Payment amount mismatch'; end if;
 if tx.currency is distinct from 'NGN' then raise exception 'Payment currency mismatch'; end if;
 if lower(coalesce(tx.platform_code,'')) is distinct from expected_platform then raise exception 'Payment platform mismatch'; end if;
 if tx.status not in ('verified','credited') or coalesce(tx.is_settled,false)<>true or tx.verified_at is null then
   raise exception 'Payment transaction is not verified and settled';
 end if;
 if tx.credited_at is not null then return jsonb_build_object('status','already_credited','transaction_ref',p_transaction_ref); end if;
 select * into fs from public.payment_fee_settings where provider=lower(p_provider) and platform_code=expected_platform and fee_code='wallet_funding' and enabled=true limit 1;
 if fs.id is not null and fs.customer_pays then
   if fs.fee_type='fixed' then fee:=fs.fee_value; else fee:=round((p_amount*fs.fee_value/100.0)::numeric,2); end if;
   if fs.minimum_fee is not null then fee:=greatest(fee,fs.minimum_fee); end if;
   if fs.maximum_fee is not null then fee:=least(fee,fs.maximum_fee); end if;
 end if;
 fee:=greatest(0,least(fee,p_amount)); net:=p_amount-fee;
 if net<=0 then raise exception 'Funding fee leaves no wallet credit'; end if;
 select id into ledger_id from public.wallet_ledger where reference='BILLSTACK:'||btrim(p_transaction_ref) for update;
 if ledger_id is not null then raise exception 'Funding ledger already exists without credited transaction marker'; end if;
 insert into public.datasub_wallets(user_id,balance,currency) values(p_user,0,'NGN') on conflict(user_id) do nothing;
 select balance into before_balance from public.datasub_wallets where user_id=p_user for update; after_balance:=before_balance+net;
 insert into public.wallet_ledger(user_id,entry_type,amount,reference,metadata,platform_code,provider,external_reference,internal_reference,direction,transaction_type,balance_before,balance_after,description)
 values(p_user,'credit',net,'BILLSTACK:'||btrim(p_transaction_ref),jsonb_build_object('gross_amount',p_amount,'customer_fee',fee,'fee_setting_id',fs.id)||coalesce(p_payload,'{}'::jsonb),expected_platform,tx.provider,tx.transaction_ref,tx.id::text,'CREDIT','wallet_funding',before_balance,after_balance,'Verified wallet funding');
 update public.datasub_wallets set balance=after_balance,updated_at=now() where user_id=p_user;
 update public.payment_transactions set status='credited',gross_amount=p_amount,customer_fee=fee,net_amount=net,fee_setting_id=fs.id,
 fee_snapshot=case when fs.id is null then '{}'::jsonb else jsonb_build_object('fee_type',fs.fee_type,'fee_value',fs.fee_value,'minimum_fee',fs.minimum_fee,'maximum_fee',fs.maximum_fee,'customer_pays',fs.customer_pays) end,
 credited_at=now(),updated_at=now() where id=tx.id and credited_at is null and is_settled=true and verified_at is not null;
 if not found then raise exception 'Payment transaction changed before credit'; end if;
 return jsonb_build_object('status','credited','transaction_ref',p_transaction_ref,'gross_amount',p_amount,'customer_fee',fee,'net_amount',net,'balance',after_balance);
end $function$;

-- Public catalogues must not call private staff helpers as anon.
-- Keep publication reads separate from authenticated administrative visibility.
alter policy "Public reads active host plans" on public.host_plans to anon, authenticated using (is_active);
create policy "Host staff reads inactive plans" on public.host_plans for select to authenticated using (private.has_product_access('host','view'));
alter policy "Public reads active domain prices" on public.host_domain_prices to anon, authenticated using (is_active);
create policy "Host staff reads inactive domain prices" on public.host_domain_prices for select to authenticated using (private.has_product_access('host','view'));
alter policy "public read active schoolpro plans" on public.schoolpro_plan_catalog to anon, authenticated using (is_active);
-- Existing authenticated superadmin ALL policy already includes read access.
revoke insert, update, delete, truncate, references, trigger on public.host_plans, public.host_domain_prices, public.schoolpro_plan_catalog from anon;

-- Administration content must not leak through customer feature queries.
alter table public.platform_feature_content
  add column audience text not null default 'customer'
  constraint platform_feature_content_audience_check check (audience in ('customer','administration'));
update public.platform_feature_content
