-- Serialize customer proof submission with invoice edits/cancellation and settlement.
-- Keep existing ownership, exact balance, saved proof and role controls.
CREATE OR REPLACE FUNCTION public.submit_direct_bank_transfer(p_platform text, p_invoice uuid, p_source_reference text, p_amount numeric, p_sender_name text, p_sender_bank text, p_customer_reference text, p_transferred_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_proof_storage_path text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_bank uuid;v_id uuid;v_enabled boolean;v_owner uuid;v_total numeric;v_paid numeric:=0;v_unit text;v_balance numeric;invoice_table text;invoice_state text;invoice_currency text;
begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) then raise exception 'Authentication required';end if;
 if p_platform='datasub' then raise exception 'DataSub requires immediate automated payment and fulfilment';end if;
 if p_platform='schoolpro' then raise exception 'SchoolPro bank transfers must use the dedicated school payment submission workflow';end if;
 if p_platform not in('host','consult','engineering','print','fabrication','compute','academy','digital_business','business_centre')
 then raise exception 'Direct transfer is not available for this platform';end if;
 if p_transferred_at>now() then raise exception 'Transfer date cannot be in the future'; end if;
 if p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) then raise exception 'Positive exact transfer amount required'; end if;
 if length(trim(coalesce(p_proof_storage_path,'')))=0 then raise exception 'Payment receipt/proof is required';end if;
 if p_proof_storage_path not like auth.uid()::text||'/%' or not exists(select 1 from storage.objects where bucket_id='direct-transfer-proofs' and name=p_proof_storage_path) then raise exception 'Saved customer-owned payment proof required'; end if;
 invoice_table:=case p_platform when 'consult' then 'consult_invoices' when 'engineering' then 'engineering_invoices' when 'print' then 'print_invoices' when 'host' then 'host_invoices' else 'business_invoices' end;
 execute format('select status,currency from public.%I where id=$1 for update',invoice_table) into invoice_state,invoice_currency using p_invoice;
 if invoice_state is null or invoice_state not in ('issued','unpaid','part_paid','overdue','awaiting_payment') or invoice_currency<>'NGN' then raise exception 'Payable NGN invoice required'; end if;
 select direct_bank_transfer_enabled into v_enabled from public.payment_platform_settings where platform_code=p_platform;
 if not coalesce(v_enabled,false) then raise exception 'Direct bank transfer is not enabled for this platform';end if;
 if p_platform='consult' then
  select pr.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid from public.consult_invoices i join public.consult_projects pr on pr.id=i.project_id where i.id=p_invoice;
 elsif p_platform='engineering' then
  select pr.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid from public.engineering_invoices i join public.engineering_projects pr on pr.id=i.project_id where i.id=p_invoice;
 elsif p_platform='print' then
  select o.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid from public.print_invoices i join public.print_orders o on o.id=i.order_id where i.id=p_invoice;
 elsif p_platform='host' then
  select i.user_id,i.amount,case when i.status='paid' then i.amount else 0 end into v_owner,v_total,v_paid from public.host_invoices i where i.id=p_invoice;
 elsif p_platform in('fabrication','compute','academy','digital_business','business_centre') then
  select o.user_id,i.amount,coalesce(i.amount_paid,0),o.unit_code into v_owner,v_total,v_paid,v_unit from public.business_invoices i join public.business_orders o on o.id=i.order_id where i.id=p_invoice;
  if v_owner is not null and v_unit<>p_platform then raise exception 'Invoice does not belong to the selected platform';end if;
 end if;
 if v_owner is null or v_owner<>auth.uid() then raise exception 'Invoice not found or does not belong to this account';end if;
 v_balance:=greatest(coalesce(v_total,0)-coalesce(v_paid,0),0);
 if v_balance<=0 then raise exception 'Invoice has no outstanding balance';end if;
 if p_amount<>v_balance then raise exception 'Transfer amount must equal the outstanding invoice balance';end if;
 if nullif(trim(coalesce(p_sender_name,'')),'') is null or nullif(trim(coalesce(p_customer_reference,'')),'') is null then raise exception 'Sender name and transfer reference are required';end if;
 if exists(select 1 from public.direct_transfer_submissions d where d.user_id=auth.uid() and d.platform_code=p_platform and d.invoice_id=p_invoice and d.status in('awaiting_verification','pending')) then raise exception 'A transfer proof for this invoice is already awaiting verification';end if;
 select id into v_bank from public.ihlink_bank_accounts where is_active=true order by is_default desc,created_at asc limit 1;
 if v_bank is null then raise exception 'IHLink direct bank account has not been configured';end if;
 insert into public.direct_transfer_submissions(user_id,platform_code,invoice_id,source_reference,bank_account_id,amount,sender_name,sender_bank,customer_reference,transferred_at,proof_storage_path,status)
 values(auth.uid(),p_platform,p_invoice,p_source_reference,v_bank,v_balance,trim(p_sender_name),nullif(trim(p_sender_bank),''),trim(p_customer_reference),p_transferred_at,p_proof_storage_path,'awaiting_verification') returning id into v_id;
 return v_id;
end $function$
;

-- Parent/student invoice reads must not confer school finance write access.
-- This private boolean helper checks only the current identity and the invoice's
-- school/student pair. Definer scope avoids recursive student/guardian RLS.
create function private.schoolpro_owns_invoice_student(p_school uuid,p_student uuid)
returns boolean language sql stable security definer set search_path='' as $$
 select auth.uid() is not null and coalesce(private.is_active_account(),false)
 and exists (
  select 1 from public.schoolpro_students s
  where s.id=p_student and s.school_id=p_school
  and (s.user_id=(select auth.uid()) or exists (
   select 1 from public.schoolpro_guardian_links g
   where g.student_id=s.id and g.guardian_user_id=(select auth.uid()) and g.status='active'
  ))
 )
$$;
