 foreach t in array array['consult_invoices','engineering_invoices','business_invoices','print_invoices','host_invoices'] loop
  execute format('alter table public.%I add column service_name text, add column service_description text, add column replaces_invoice_id uuid unique references public.%I(id)',t,t);
 end loop;
end $$;
