update public.consult_invoices i set service_name=i.title,service_description='Project: '||p.name from public.consult_projects p where p.id=i.project_id;
update public.engineering_invoices i set service_name=i.title,service_description='Project: '||p.name from public.engineering_projects p where p.id=i.project_id;
update public.business_invoices i set service_name=o.title,service_description=o.requirements from public.business_orders o where o.id=i.order_id;
update public.print_invoices i set service_name=o.title,service_description='Print order: '||o.id::text from public.print_orders o where o.id=i.order_id;
