 original_status text not null, new_service_name text not null,
 new_description text not null, new_amount numeric not null check(new_amount>0 and new_amount::text not in('NaN','Infinity','-Infinity') and new_amount=round(new_amount,2)),
 reason text not null check(length(trim(reason))>=3),
