-- Only this allowlist determines SQL identifiers. Lock invoice before its parent,
-- matching payment submission/reconciliation lock order.
create function private.service_invoice_context(p_platform text,p_invoice uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare t text; pt text; fk text; i jsonb; p jsonb; owner_id uuid; editable boolean;
begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) then raise exception 'Authentication required'; end if;
 case p_platform
 when 'consult' then t:='consult_invoices';pt:='consult_projects';fk:='project_id';
 when 'engineering' then t:='engineering_invoices';pt:='engineering_projects';fk:='project_id';
 when 'host' then t:='host_invoices';pt:='host_orders';fk:='order_id';
 when 'print' then t:='print_invoices';pt:='print_orders';fk:='order_id';
 when 'fabrication','compute','academy','digital_business','business_centre' then t:='business_invoices';pt:='business_orders';fk:='order_id';
 else raise exception 'Unsupported commercial invoice platform'; end case;
 execute format('select to_jsonb(x) from public.%I x where id=$1 for update',t) into i using p_invoice;
 if i is null then raise exception 'Invoice not found';end if;
 execute format('select to_jsonb(x) from public.%I x where id=$1 for update',pt) into p using (i->>fk)::uuid;
 if p is null and p_platform<>'host' then raise exception 'Service not found';end if;
 if t='business_invoices' and p->>'unit_code' is distinct from p_platform then raise exception 'Invoice platform mismatch';end if;
 owner_id:=coalesce((p->>'user_id')::uuid,(i->>'user_id')::uuid);
 editable:=case when t='business_invoices' then private.business_staff_allowed(p_platform,'edit') when p_platform='print' then private.print_staff_permission('edit') else private.has_product_access(p_platform,'edit') end;
 if owner_id is distinct from auth.uid() and not coalesce(editable,false) then raise exception 'Invoice access denied';end if;
 return jsonb_build_object('table',t,'parent_table',pt,'parent_id',i->>fk,'owner',owner_id,'editable',coalesce(editable,false),'invoice',i,'parent',p);
end $$;
revoke all on function private.service_invoice_context(text,uuid) from public,anon,authenticated;

create function private.service_invoice_unsettled(p_context jsonb,p_platform text) returns void
language plpgsql security definer set search_path='' as $$
declare i jsonb:=p_context->'invoice'; linked boolean; intent_table text;
begin
 if coalesce((i->>'amount_paid')::numeric,0)<>0 or i->>'status' in('paid','part_paid','partially_paid') or i->>'paid_at' is not null or i->>'payment_id' is not null or nullif(i->>'payment_reference','') is not null then raise exception 'Settled invoices cannot be changed';end if;
 if exists(select 1 from public.direct_transfer_submissions where invoice_id=(i->>'id')::uuid and platform_code=p_platform and status not in('rejected','cancelled')) then raise exception 'Resolve the payment proof before changing this invoice';end if;
 intent_table:=replace(p_context->>'table','_invoices','_payment_intents');
 execute format('select exists(select 1 from public.%I where invoice_id=$1 and status not in (''failed'',''cancelled'',''expired'',''rejected''))',intent_table) into linked using (i->>'id')::uuid;
 if linked then raise exception 'Invoice has an unresolved or settled payment intent';end if;
end $$;
revoke all on function private.service_invoice_unsettled(jsonb,text) from public,anon,authenticated;

create function private.manage_service_invoice(p_platform text,p_invoice uuid,p_action text,p_version timestamptz,p_reason text,p_name text,p_description text,p_amount numeric) returns jsonb
language plpgsql security definer set search_path='' as $$
declare c jsonb; i jsonb; t text; child uuid; new_id uuid; state text; changed uuid;
begin
 c:=private.service_invoice_context(p_platform,p_invoice);i:=c->'invoice';t:=c->>'table';
 if not (c->>'editable')::boolean then raise exception 'Invoice editing permission required';end if;
 if p_action is null or p_action not in('cancel','regenerate','revise') then raise exception 'Invalid invoice action';end if;
 if length(trim(coalesce(p_reason,'')))<3 then raise exception 'A reason is required';end if;
 -- Retries can reuse the one replacement without touching either invoice.
 if p_action='regenerate' then
  if i->>'status'<>'cancelled' then raise exception 'Only a cancelled invoice can be regenerated';end if;
  execute format('select id from public.%I where replaces_invoice_id=$1',t) into child using p_invoice;
  if child is not null then return jsonb_build_object('invoice_id',child,'reused',true);end if;
 end if;
 if p_version is null or (i->>'updated_at')::timestamptz is distinct from p_version then raise exception 'Invoice changed; refresh before retrying';end if;
 perform private.service_invoice_unsettled(c,p_platform);
 state:=i->>'status';
 if p_action='cancel' then
  if state not in('draft','issued','unpaid','overdue','awaiting_payment') then raise exception 'Invoice cannot be cancelled in this state';end if;
  execute format('update public.%I set status=''cancelled'',updated_at=clock_timestamp() where id=$1',t) using p_invoice;
  update public.service_invoice_changes set status='cancelled',responded_at=clock_timestamp() where invoice_id=p_invoice and platform_code=p_platform and status='pending';
 elsif p_action='regenerate' then
  if exists(select 1 from public.service_invoice_changes where invoice_id=p_invoice and platform_code=p_platform and status='pending') then raise exception 'Resolve invoice revision first';end if;
  -- Serialize siblings under the parent lock and reject other active invoices.
  execute format('select id from public.%I where %I=$1 and id<>$2 and status<>''cancelled'' limit 1',t,case when p_platform in('consult','engineering') then 'project_id' else 'order_id' end) into child using (c->>'parent_id')::uuid,p_invoice;
  if child is not null then raise exception 'This service already has an active invoice';end if;
  new_id:=gen_random_uuid();
  i:=i||jsonb_build_object('id',new_id,'invoice_number','INV-'||upper(replace(new_id::text,'-','')),'status',case when p_platform in('host','print') then 'unpaid' else 'issued' end,'amount_paid',0,'paid_at',null,'payment_reference',null,'payment_id',null,'created_at',clock_timestamp(),'updated_at',clock_timestamp(),'replaces_invoice_id',p_invoice);
  -- Original quote/proposal associations remain on the immutable predecessor.
  if p_platform='consult' then i:=i||jsonb_build_object('quotation_id',null,'proposal_id',null);end if;
  execute format('insert into public.%I select (jsonb_populate_record(null::public.%I,$1)).*',t,t) using i;
 elsif p_action='revise' then
  if state not in('issued','unpaid','overdue','awaiting_payment') then raise exception 'Only an unpaid issued invoice can be revised';end if;
  if p_amount is null or p_amount<=0 or p_amount::text in('NaN','Infinity','-Infinity') or p_amount<>round(p_amount,2) then raise exception 'Amount must be positive with at most two decimals';end if;
  if length(trim(coalesce(p_name,'')))<3 or length(trim(coalesce(p_description,'')))<3 then raise exception 'Service name and description are required';end if;
  insert into public.service_invoice_changes(platform_code,invoice_id,user_id,created_by,original_status,new_service_name,new_description,new_amount,reason) values(p_platform,p_invoice,(c->>'owner')::uuid,auth.uid(),state,trim(p_name),trim(p_description),p_amount,trim(p_reason)) returning id into changed;
  execute format('update public.%I set status=''draft'',updated_at=clock_timestamp() where id=$1',t) using p_invoice;
 end if;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'service_invoice_'||p_action,p_platform,'invoice',p_invoice::text,jsonb_build_object('reason',trim(p_reason),'previous',c->'invoice','replacement',new_id,'change_id',changed));
 return jsonb_build_object('invoice_id',coalesce(new_id,p_invoice),'change_id',changed);
end $$;
revoke all on function private.manage_service_invoice(text,uuid,text,timestamptz,text,text,text,numeric) from public,anon;
grant execute on function private.manage_service_invoice(text,uuid,text,timestamptz,text,text,text,numeric) to authenticated;
create function public.manage_service_invoice(p_platform text,p_invoice uuid,p_action text,p_version timestamptz,p_reason text,p_name text default null,p_description text default null,p_amount numeric default null) returns jsonb language sql security invoker set search_path='' as $$ select private.manage_service_invoice(p_platform,p_invoice,p_action,p_version,p_reason,p_name,p_description,p_amount) $$;
revoke all on function public.manage_service_invoice(text,uuid,text,timestamptz,text,text,text,numeric) from public,anon;
grant execute on function public.manage_service_invoice(text,uuid,text,timestamptz,text,text,text,numeric) to authenticated;

create function private.respond_service_invoice_change(p_change uuid,p_accept boolean) returns jsonb
language plpgsql security definer set search_path='' as $$
declare r public.service_invoice_changes%rowtype;c jsonb;t text;
begin
 -- Read identifier, then lock invoice first to avoid cancellation deadlocks.
 select * into r from public.service_invoice_changes where id=p_change;
 if r.id is null then raise exception 'Invoice revision not found';end if;
 c:=private.service_invoice_context(r.platform_code,r.invoice_id);t:=c->>'table';
 select * into r from public.service_invoice_changes where id=p_change for update;
 if auth.uid() is distinct from r.user_id or auth.uid() is distinct from (c->>'owner')::uuid then raise exception 'Only the invoice owner can respond';end if;
 if p_accept is null then raise exception 'Choose accept or reject';end if;
 if r.status in('accepted','rejected') then return jsonb_build_object('status',r.status);end if;
 if r.status<>'pending' or c->'invoice'->>'status'<>'draft' then raise exception 'Invoice revision is no longer pending';end if;
 perform private.service_invoice_unsettled(c,r.platform_code);
 if p_accept then
  execute format('update public.%I set amount=$1,service_name=$2,service_description=$3,status=$4,updated_at=clock_timestamp() where id=$5',t) using r.new_amount,r.new_service_name,r.new_description,r.original_status,r.invoice_id;
  -- Keep the hosting order's payable amount consistent for provisioning checks.
  if r.platform_code='host' and c->>'parent_id' is not null then update public.host_orders set amount=r.new_amount,updated_at=clock_timestamp() where id=(c->>'parent_id')::uuid;end if;
 else
  execute format('update public.%I set status=$1,updated_at=clock_timestamp() where id=$2',t) using r.original_status,r.invoice_id;
 end if;
 update public.service_invoice_changes set status=case when p_accept then 'accepted' else 'rejected' end,responded_at=clock_timestamp() where id=p_change;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'service_invoice_revision_response',r.platform_code,'invoice',r.invoice_id::text,jsonb_build_object('change_id',p_change,'accepted',p_accept));
 return jsonb_build_object('status',case when p_accept then 'accepted' else 'rejected' end);
end $$;
revoke all on function private.respond_service_invoice_change(uuid,boolean) from public,anon;
grant execute on function private.respond_service_invoice_change(uuid,boolean) to authenticated;
create function public.respond_service_invoice_change(p_change uuid,p_accept boolean) returns jsonb language sql security invoker set search_path='' as $$select private.respond_service_invoice_change(p_change,p_accept)$$;
revoke all on function public.respond_service_invoice_change(uuid,boolean) from public,anon;
grant execute on function public.respond_service_invoice_change(uuid,boolean) to authenticated;

-- Company SchoolPro subscriptions retain published annual plan pricing. School
-- student fees belong to the school's separate finance workflow.
create function private.manage_schoolpro_subscription_invoice(p_invoice uuid,p_action text,p_version timestamptz,p_reason text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare i public.schoolpro_subscription_intents%rowtype;child uuid;plan public.schoolpro_subscription_catalog%rowtype;new_id uuid;
begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) or not coalesce(private.has_product_access('schoolpro','edit'),false) then raise exception 'SchoolPro company invoice editing permission required';end if;
 if p_action is null or p_action not in('cancel','regenerate') or length(trim(coalesce(p_reason,'')))<3 then raise exception 'Choose cancel or regenerate and provide a reason';end if;
 select * into i from public.schoolpro_subscription_intents where id=p_invoice for update;
 if i.id is null then raise exception 'Subscription invoice not found';end if;
 if p_action='regenerate' then
  if i.status<>'cancelled' then raise exception 'Only a cancelled subscription invoice can be regenerated';end if;
  select id into child from public.schoolpro_subscription_intents where replaces_invoice_id=i.id;
  if child is not null then return jsonb_build_object('invoice_id',child,'reused',true);end if;
 end if;
 if p_version is null or i.updated_at is distinct from p_version then raise exception 'Invoice changed; refresh before retrying';end if;
 if i.payment_method<>'bank_transfer' or i.virtual_account_id is not null or i.paid_at is not null or i.transaction_ref is not null or i.status not in('pending','cancelled') then raise exception 'Historical or settled subscription invoices cannot be changed';end if;
 if exists(select 1 from public.direct_transfer_submissions where invoice_id=i.id and platform_code='schoolpro_subscription' and status not in('rejected','cancelled')) then raise exception 'Resolve the payment proof before changing this invoice';end if;
 if p_action='cancel' then
  if i.status<>'pending' then raise exception 'Only a pending invoice can be cancelled';end if;
  update public.schoolpro_subscription_intents set status='cancelled',updated_at=clock_timestamp() where id=i.id;
 else
  perform 1 from public.schoolpro_schools where id=i.school_id for update;
  if exists(select 1 from public.schoolpro_subscription_intents where school_id=i.school_id and status='pending') then raise exception 'The school already has a pending subscription invoice';end if;
  if not exists(select 1 from public.schoolpro_schools where id=i.school_id and status<>'suspended') then raise exception 'School is unavailable';end if;
  select * into plan from public.schoolpro_subscription_catalog where id=i.catalog_id and active=true;
  if plan.id is null or plan.annual_price<=0 or plan.annual_price::text in('NaN','Infinity','-Infinity') or plan.annual_price<>round(plan.annual_price,2) then raise exception 'An active published annual plan is required';end if;
  new_id:=gen_random_uuid();
