-- Proposal retries resolve the latest invoice while original associations remain immutable.
CREATE OR REPLACE FUNCTION public.respond_consult_proposal(p_proposal uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v public.consult_proposals; q public.consult_quotations; inv uuid;
 v_project uuid; v_owner uuid; v_actor uuid := auth.uid();
begin
 if v_actor is null then raise exception 'Authentication required'; end if;
 if p_action is null or p_action not in('accepted','revision_requested','rejected') then raise exception 'Invalid action'; end if;
 select project_id into v_project from public.consult_proposals where id=p_proposal;
 select user_id into v_owner from public.consult_projects where id=v_project for update;
 if not found or v_owner is distinct from v_actor then raise exception 'Proposal not found'; end if;
 select * into v from public.consult_proposals where id=p_proposal and user_id=v_actor for update;
 if not found then raise exception 'Proposal not found'; end if;
 if v.status='accepted' and p_action='accepted' then
  with recursive history as (select id,0 depth from public.consult_invoices where proposal_id=v.id union all select i.id,h.depth+1 from public.consult_invoices i join history h on i.replaces_invoice_id=h.id) select id into inv from history order by depth desc limit 1;
  return jsonb_build_object('status','accepted','invoice_id',inv);
 end if;
 if v.status not in('sent','revision_requested') then raise exception 'Proposal is not awaiting response'; end if;
 if exists(select 1 from public.consult_proposals where project_id=v_project and version>v.version) then
  raise exception 'Review the latest proposal version';
 end if;
 if v.valid_until<current_date then raise exception 'Proposal has expired'; end if;
 if p_action='accepted' then
  select * into q from public.consult_quotations where project_id=v_project and status='accepted';
  if not found or q.amount is null or q.amount<=0 then raise exception 'Accept a valid positive quotation before accepting the proposal'; end if;
  select id into inv from public.consult_invoices where quotation_id=q.id for update;
  if inv is not null and not exists(select 1 from public.consult_invoices where id=inv and project_id=v_project and amount=q.amount and currency='NGN' and status='draft' and proposal_id is null and amount_paid=0) then
   raise exception 'This quotation already has an issued invoice; reconcile before accepting another proposal';
  end if;
 end if;
 update public.consult_proposals set status=p_action,
  accepted_at=case when p_action='accepted' then now() else accepted_at end,
  revision_requested_at=case when p_action='revision_requested' then now() else revision_requested_at end,
  rejected_at=case when p_action='rejected' then now() else rejected_at end,updated_at=now() where id=v.id;
 if p_action='accepted' then
  if inv is not null then
   update public.consult_invoices set proposal_id=v.id,title=v.title,status='issued',due_at=current_date+7,updated_at=now() where id=inv;
  else
  insert into public.consult_invoices(project_id,proposal_id,quotation_id,invoice_number,title,amount,currency,due_at,status)
  values(v_project,v.id,q.id,'CONS-'||to_char(now(),'YYYYMMDD')||'-'||upper(replace(v.id::text,'-','')),v.title,q.amount,'NGN',current_date+7,'issued')
  returning id into inv;
  end if;
  update public.consult_projects set quoted_amount=q.amount,
   outstanding_amount=(select coalesce(sum(greatest(amount-coalesce(amount_paid,0),0)),0) from public.consult_invoices where project_id=v_project and status not in ('cancelled','draft')),
   updated_at=now() where id=v_project;
 end if;
 insert into public.consult_activity_logs(project_id,actor_user_id,action,details)
 values(v_project,v_actor,'proposal_'||p_action,jsonb_build_object('proposal_id',v.id,'invoice_id',inv));
 return jsonb_build_object('status',p_action,'invoice_id',inv);
end $function$
;

-- Cancelled drafts remain drafts; regeneration never substitutes for approval.
do $$ declare t text; begin
 foreach t in array array['consult_invoices','engineering_invoices','business_invoices','print_invoices','host_invoices'] loop
  execute format('alter table public.%I add column cancelled_from_status text check(cancelled_from_status is null or cancelled_from_status in (''draft'',''issued'',''unpaid'',''overdue'',''awaiting_payment''))',t);
 end loop;
end $$;
create or replace function private.manage_service_invoice(p_platform text,p_invoice uuid,p_action text,p_version timestamptz,p_reason text,p_name text,p_description text,p_amount numeric) returns jsonb
language plpgsql security definer set search_path='' as $$
declare c jsonb; i jsonb; t text; child uuid; new_id uuid; state text; changed uuid;
begin
 c:=private.service_invoice_context(p_platform,p_invoice);i:=c->'invoice';t:=c->>'table';
 if not (c->>'editable')::boolean then raise exception 'Invoice editing permission required';end if;
 if p_action is null or p_action not in('cancel','regenerate','revise') then raise exception 'Invalid invoice action';end if;
 if length(trim(coalesce(p_reason,'')))<3 then raise exception 'A reason is required';end if;
 -- Retries can reuse the one replacement without touching either invoice.
 if p_action='regenerate' then
  if i->>'status'<>'cancelled' then raise exception 'Only a cancelled invoice can be regenerated';end if;
  execute format('select id from public.%I where replaces_invoice_id=$1',t) into child using p_invoice;
  if child is not null then return jsonb_build_object('invoice_id',child,'reused',true);end if;
 end if;
 if p_version is null or (i->>'updated_at')::timestamptz is distinct from p_version then raise exception 'Invoice changed; refresh before retrying';end if;
 perform private.service_invoice_unsettled(c,p_platform);
 state:=i->>'status';
 if p_action='cancel' then
  if state not in('draft','issued','unpaid','overdue','awaiting_payment') then raise exception 'Invoice cannot be cancelled in this state';end if;
  execute format('update public.%I set cancelled_from_status=$2,status=''cancelled'',updated_at=clock_timestamp() where id=$1',t) using p_invoice,coalesce((select original_status from public.service_invoice_changes where invoice_id=p_invoice and platform_code=p_platform and status='pending'),state);
  update public.service_invoice_changes set status='cancelled',responded_at=clock_timestamp() where invoice_id=p_invoice and platform_code=p_platform and status='pending';
 elsif p_action='regenerate' then
  if exists(select 1 from public.service_invoice_changes where invoice_id=p_invoice and platform_code=p_platform and status='pending') then raise exception 'Resolve invoice revision first';end if;
  -- Serialize siblings under the parent lock and reject other active invoices.
  execute format('select id from public.%I where %I=$1 and id<>$2 and status<>''cancelled'' limit 1',t,case when p_platform in('consult','engineering') then 'project_id' else 'order_id' end) into child using (c->>'parent_id')::uuid,p_invoice;
  if child is not null then raise exception 'This service already has an active invoice';end if;
  new_id:=gen_random_uuid();
  i:=i||jsonb_build_object('id',new_id,'invoice_number','INV-'||upper(replace(new_id::text,'-','')),'status',coalesce(i->>'cancelled_from_status','draft'),'cancelled_from_status',null,'amount_paid',0,'paid_at',null,'payment_reference',null,'payment_id',null,'created_at',clock_timestamp(),'updated_at',clock_timestamp(),'replaces_invoice_id',p_invoice);
  -- Original quote/proposal associations remain on the immutable predecessor.
  if p_platform='consult' then i:=i||jsonb_build_object('quotation_id',null,'proposal_id',null);end if;
  execute format('insert into public.%I select (jsonb_populate_record(null::public.%I,$1)).*',t,t) using i;
 elsif p_action='revise' then
  if state not in('issued','unpaid','overdue','awaiting_payment') then raise exception 'Only an unpaid issued invoice can be revised';end if;
  if p_amount is null or p_amount<=0 or p_amount::text in('NaN','Infinity','-Infinity') or p_amount<>round(p_amount,2) then raise exception 'Amount must be positive with at most two decimals';end if;
  if length(trim(coalesce(p_name,'')))<3 or length(trim(coalesce(p_description,'')))<3 then raise exception 'Service name and description are required';end if;
  insert into public.service_invoice_changes(platform_code,invoice_id,user_id,created_by,original_status,new_service_name,new_description,new_amount,reason) values(p_platform,p_invoice,(c->>'owner')::uuid,auth.uid(),state,trim(p_name),trim(p_description),p_amount,trim(p_reason)) returning id into changed;
  execute format('update public.%I set status=''draft'',updated_at=clock_timestamp() where id=$1',t) using p_invoice;
 end if;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'service_invoice_'||p_action,p_platform,'invoice',p_invoice::text,jsonb_build_object('reason',trim(p_reason),'previous',c->'invoice','replacement',new_id,'change_id',changed));
 return jsonb_build_object('invoice_id',coalesce(new_id,p_invoice),'change_id',changed);
end $$;

